var SA_P2 = [
  {"id":"pedsa2-1-1","src":"p2","num":"1.1","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":3,"stem":"Which of the following is a LIMIT AGE rather than a median age?","options":["Smiling at 6 weeks","Sitting without support by 9 months","Walking at 12 months","First words at 12 months","Pincer grip at 10 months"],"answer":1,"keyLetter":"B","explanation":"A median age is when half of children have acquired the skill; a limit age is the age by which it should have been acquired — usually two standard deviations from the mean. Failure to reach a limit age is what triggers assessment."},
  {"id":"pedsa2-1-2","src":"p2","num":"1.2","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":3,"stem":"A child born at 28 weeks' gestation is seen at 9 months of chronological age. How should his development be assessed?","options":["At his chronological age of 9 months","Corrected for prematurity, i.e. at 6 months, until about 2 years of age","Corrected for prematurity indefinitely","No correction is ever applied","Corrected only for gross motor skills"],"answer":1,"keyLetter":"B","explanation":"Development is corrected for gestation until about 2 years of age. Failing to correct labels a normal preterm infant as delayed."},
  {"id":"pedsa2-1-3","src":"p2","num":"1.3","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":4,"stem":"Which pattern of hand use is ALWAYS abnormal before 12 months of age?","options":["Palmar grasp","Transferring objects between hands","Definite hand preference","Pincer grip","Casting objects"],"answer":2,"keyLetter":"C","explanation":"Hand preference before 12 months is abnormal and suggests a hemiplegia — the \"preference\" is really weakness on the other side."},
  {"id":"pedsa2-1-4","src":"p2","num":"1.4","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":4,"stem":"Which of the following describes GLOBAL developmental delay?","options":["Delay confined to speech and language","Delay in two or more developmental domains","Loss of previously acquired skills","Delay in gross motor skills only","Normal development with abnormal behaviour"],"answer":1,"keyLetter":"B","explanation":"Global delay = two or more domains. Loss of skills is REGRESSION (option C), which is far more serious and always needs investigation for a neurodegenerative or metabolic cause."},
  {"id":"pedsa2-1-5","src":"p2","num":"1.5","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":4,"stem":"At what age would you expect a child to normally build a tower of 6 cubes and join two words together?","options":["12 months","18 months","2 years","3 years","4 years"],"answer":2,"keyLetter":"C","explanation":"At 2 years a child typically builds a tower of about 6 cubes, joins two words, runs, and uses a spoon. At 3 years the tower is about 9 cubes and speech is in short sentences."},
  {"id":"pedsa2-1-6","src":"p2","num":"1.6","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":5,"stem":"Which screening test is used for hearing in the newborn period?","options":["Distraction test","Otoacoustic emissions, with automated auditory brainstem response if abnormal","Pure tone audiometry","Speech discrimination testing","Tympanometry"],"answer":1,"keyLetter":"B","explanation":"Universal newborn hearing screening uses otoacoustic emissions, with automated auditory brainstem response for those who do not pass. Pure tone audiometry needs a cooperative child (about 4 years and over)."},
  {"id":"pedsa2-1-7","src":"p2","num":"1.7","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":5,"stem":"Parents are worried that their 20-month-old says only a few single words. Which additional feature would most raise concern about a hearing impairment rather than isolated language delay?","options":["He has an older sibling who talks for him","He does not turn to his name and had recurrent otitis media with effusion","He points to what he wants","He plays imaginatively","He is bilingual at home"],"answer":1,"keyLetter":"B","explanation":"Every child with delayed speech must have a hearing test. Not turning to sound plus a history of otitis media with effusion (glue ear) points to a conductive loss. Bilingualism does not cause delay, and pointing and imaginative play are reassuring for social communication."},
  {"id":"pedsa2-1-8","src":"p2","num":"1.8","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":6,"stem":"An absent red reflex is detected in a 6-week-old. What is the most important diagnosis to exclude?","options":["Refractive error","Congenital cataract and retinoblastoma","Conjunctivitis","Blocked nasolacrimal duct","Strabismus"],"answer":1,"keyLetter":"B","explanation":"An absent or white red reflex (leukocoria) requires same-day ophthalmology referral — congenital cataract needs early surgery for vision to develop, and retinoblastoma is life-threatening."},
  {"id":"pedsa2-1-9","src":"p2","num":"1.9","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":6,"stem":"A squint is noted in a 3-year-old. Which statement is correct?","options":["All squints resolve spontaneously by school age","Untreated squint may cause amblyopia, so referral is required","Squint after 6 weeks of age is normal","Squint never indicates intracranial pathology","Patching the squinting eye is the treatment"],"answer":1,"keyLetter":"B","explanation":"A persistent squint causes amblyopia because the brain suppresses one image. Treatment is patching the GOOD eye to force use of the weaker one, with correction of refractive error. A new squint may also signal raised intracranial pressure or retinoblastoma."},
  {"id":"pedsa2-1-10","src":"p2","num":"1.10","kind":"sba","block":"Block 1 · Normal Development, Hearing and Vision 10 QUESTIONS","page":7,"stem":"Which primitive reflex, if it persists beyond the expected age, most suggests an underlying neurological abnormality?","options":["Moro reflex persisting beyond 6 months","Rooting reflex at 2 months","Palmar grasp at 3 months","Stepping reflex at 4 weeks","Asymmetrical tonic neck reflex at 3 months"],"answer":0,"keyLetter":"A","explanation":"Primitive reflexes normally disappear in the first few months as cortical control develops. Persistence beyond the expected age — for example a Moro after about 6 months — suggests a central motor disorder such as cerebral palsy."},
  {"id":"pedsa2-2-1","src":"p2","num":"2.1","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":8,"stem":"Which statement best defines cerebral palsy?","options":["A progressive disorder of movement and posture","A permanent disorder of movement and posture due to a NON-PROGRESSIVE lesion of the developing brain","A disorder of the peripheral nerves in infancy","A condition always associated with learning disability","A disorder that appears only after the age of 5 years"],"answer":1,"keyLetter":"B","explanation":"The lesion is non-progressive, but the clinical picture changes as the child grows — which is why signs may become more obvious over the first two years. Progressive deterioration means the diagnosis is something else."},
  {"id":"pedsa2-2-2","src":"p2","num":"2.2","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":8,"stem":"When does the causal brain injury occur in the majority of children with cerebral palsy?","options":["Antenatally","During labour and delivery","In the first week after birth","Between 1 and 2 years of age","After the age of 5 years"],"answer":0,"keyLetter":"A","explanation":"About 80% of cases are ANTENATAL in origin — vascular occlusion, cortical migration disorders, structural maldevelopment, congenital infection. Only around 10% follow intrapartum hypoxic–ischaemic injury, which is why cerebral palsy is not synonymous with \"birth asphyxia\"."},
  {"id":"pedsa2-2-3","src":"p2","num":"2.3","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":9,"stem":"A 10-month-old ex-preterm infant has stiff, scissored legs with brisk reflexes and up-going plantars, and normal arms. Which type of cerebral palsy is this?","options":["Spastic hemiplegia","Spastic DIPLEGIA","Dyskinetic cerebral palsy","Ataxic cerebral palsy","Spastic quadriplegia"],"answer":1,"keyLetter":"B","explanation":"Diplegia = legs much more affected than arms, classically after preterm birth with periventricular injury, because the leg fibres run closest to the ventricles."},
  {"id":"pedsa2-2-4","src":"p2","num":"2.4","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":9,"stem":"Which form of cerebral palsy is most associated with severe learning difficulties, seizures and feeding problems?","options":["Spastic hemiplegia","Spastic diplegia","Spastic QUADRIPLEGIA","Mild ataxia","Isolated dyskinesia"],"answer":2,"keyLetter":"C","explanation":"Quadriplegia is the most severe pattern — all four limbs, often with seizures, microcephaly, severe learning difficulty and swallowing problems with aspiration."},
  {"id":"pedsa2-2-5","src":"p2","num":"2.5","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":10,"stem":"Dyskinetic cerebral palsy with chorea and athetosis classically follows damage to which structure?","options":["Cerebellum","Basal ganglia","Anterior horn cells","Peripheral nerves","Posterior columns"],"answer":1,"keyLetter":"B","explanation":"Basal ganglia (extrapyramidal) damage — historically from kernicterus, now more often from hypoxic–ischaemic injury. Intellect is often relatively preserved, which matters enormously for communication aids."},
  {"id":"pedsa2-2-6","src":"p2","num":"2.6","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":10,"stem":"A 14-month-old is not yet sitting, has definite right hand preference and a fisted left hand. What is the single most appropriate action?","options":["Reassure and review in 6 months","Refer for developmental assessment — early hand preference suggests a hemiplegia","Arrange a hearing test only","Start physiotherapy without assessment","Repeat the newborn examination"],"answer":1,"keyLetter":"B","explanation":"Hand preference before 12 months is abnormal. With failure to sit by the limit age, this needs full assessment for spastic hemiplegia."},
  {"id":"pedsa2-2-7","src":"p2","num":"2.7","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":11,"stem":"Which professional group is LEAST likely to be needed in the routine multidisciplinary management of a child with cerebral palsy?","options":["Physiotherapist","Occupational therapist","Speech and language therapist","Dietitian","Interventional radiologist"],"answer":4,"keyLetter":"E","explanation":"Cerebral palsy care is multidisciplinary and lifelong — physiotherapy, occupational therapy, speech and language therapy (communication AND swallowing), dietetics, orthotics, orthopaedics, paediatric neurology, education and social care."},
  {"id":"pedsa2-2-8","src":"p2","num":"2.8","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":11,"stem":"A child with spastic cerebral palsy has painful hip subluxation. Which statement is correct?","options":["Hip surveillance is unnecessary if the child walks","Hip surveillance with regular examination and radiographs is part of routine care","Subluxation never causes pain","Surgery is contraindicated in cerebral palsy","Scoliosis is unrelated to cerebral palsy"],"answer":1,"keyLetter":"B","explanation":"Hip surveillance is standard because spasticity progressively displaces the hip, and a dislocated hip is painful and hard to treat late. Scoliosis is another recognised musculoskeletal complication."},
  {"id":"pedsa2-2-9","src":"p2","num":"2.9","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":12,"stem":"Which is the most appropriate first-line treatment for focal spasticity limiting function in a single muscle group?","options":["Oral diazepam long term","Botulinum toxin injection with physiotherapy","Immediate tendon lengthening surgery","Bed rest","Intrathecal baclofen for all children"],"answer":1,"keyLetter":"B","explanation":"Focal spasticity → botulinum toxin plus physiotherapy and orthoses. Generalised spasticity may need oral baclofen or intrathecal baclofen; surgery is reserved for fixed contractures and deformity."},
  {"id":"pedsa2-2-10","src":"p2","num":"2.10","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":12,"stem":"A 3-year-old has lost the ability to walk and to speak in sentences over 6 months. What does this pattern indicate?","options":["Cerebral palsy","Global developmental delay","REGRESSION — investigate for a neurodegenerative or metabolic disorder","Normal variation","Isolated language disorder"],"answer":2,"keyLetter":"C","explanation":"Loss of previously acquired skills is never cerebral palsy — the lesion in cerebral palsy is non-progressive. Regression demands investigation for neurodegenerative, metabolic or epileptic encephalopathy causes."},
  {"id":"pedsa2-2-11","src":"p2","num":"2.11","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":13,"stem":"Which feature would most suggest autism spectrum disorder rather than isolated language delay in a 3-year-old?","options":["Uses fewer than 50 words","Does not point to share interest, avoids eye contact and has restricted repetitive interests","Speaks only at home","Has a family history of late talking","Was born preterm"],"answer":1,"keyLetter":"B","explanation":"Autism is defined by impaired social communication and interaction plus restricted, repetitive behaviours and interests. Failure of joint attention (pointing to share) is one of the earliest and most useful discriminators."},
  {"id":"pedsa2-2-12","src":"p2","num":"2.12","kind":"sba","block":"Block 2 · Developmental Problems and Cerebral Palsy 12 QUESTIONS","page":13,"stem":"Which statement about attention deficit hyperactivity disorder is correct?","options":["Symptoms must be present in only one setting","Symptoms of inattention, hyperactivity and impulsivity must be present in more than one setting and impair function","It is diagnosed on a blood test","Medication is always first line in preschool children","It always resolves by adolescence"],"answer":1,"keyLetter":"B","explanation":"ADHD requires pervasive symptoms — home AND school — causing impairment. Management begins with parent training and educational support; medication is added in older children when symptoms remain impairing."},
  {"id":"pedsa2-3-1","src":"p2","num":"3.1","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":14,"stem":"What is the commonest cytogenetic cause of Down syndrome?","options":["Robertsonian translocation","Non-disjunction (trisomy 21)","Mosaicism","Deletion of chromosome 21","Uniparental disomy"],"answer":1,"keyLetter":"B","explanation":"Non-disjunction accounts for about 94%, translocation about 5% and mosaicism about 1%. Only the translocation form carries a substantially increased recurrence risk and requires parental karyotyping."},
  {"id":"pedsa2-3-2","src":"p2","num":"3.2","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":14,"stem":"Parents of a newborn with translocation Down syndrome ask about recurrence. What is the correct advice?","options":["The recurrence risk is the same as the general population","Both parents should be karyotyped, as one may carry a balanced translocation with a substantially higher recurrence risk","Recurrence is impossible","Only the mother's age matters","Prenatal diagnosis is not available"],"answer":1,"keyLetter":"B","explanation":"In translocation Down syndrome, one parent may carry a balanced translocation. Karyotyping both parents is essential for accurate counselling, and the recurrence risk can be considerable — much higher than the age-related risk of non-disjunction."},
  {"id":"pedsa2-3-3","src":"p2","num":"3.3","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":15,"stem":"Which is the most common serious congenital abnormality associated with Down syndrome?","options":["Congenital heart disease, especially atrioventricular septal defect","Renal agenesis","Cleft lip","Neural tube defect","Congenital diaphragmatic hernia"],"answer":0,"keyLetter":"A","explanation":"Around 40% have congenital heart disease, classically an atrioventricular septal defect — which is why echocardiography is part of the initial work-up. Duodenal atresia, Hirschsprung disease, hypothyroidism, atlantoaxial instability, leukaemia and hearing/vision problems are the other associations."},
  {"id":"pedsa2-3-4","src":"p2","num":"3.4","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":15,"stem":"A 14-year-old girl has short stature, no breast development, a webbed neck and widely spaced nipples. Blood pressure is 145/90 in the right arm. What is the most likely diagnosis and the key associated lesion to exclude?","options":["Down syndrome — atrioventricular septal defect","Turner syndrome — coarctation of the aorta and bicuspid aortic valve","Noonan syndrome — pulmonary stenosis","Marfan syndrome — aortic root dilatation","Klinefelter syndrome — no cardiac lesion"],"answer":1,"keyLetter":"B","explanation":"Turner syndrome (45,X0): short stature, delayed puberty from ovarian dysgenesis, webbed neck, wide carrying angle, coarctation and bicuspid aortic valve, and renal anomalies. Treatment includes growth hormone and oestrogen replacement."},
  {"id":"pedsa2-3-5","src":"p2","num":"3.5","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":16,"stem":"A condition shows male-to-male transmission and affects both sexes equally in every generation. What is the inheritance pattern?","options":["Autosomal recessive","Autosomal dominant","X-linked recessive","X-linked dominant","Mitochondrial"],"answer":1,"keyLetter":"B","explanation":"Father-to-son transmission excludes any X-linked pattern. Autosomal dominant conditions affect both sexes, appear in every generation, and carry a 50% risk to each offspring."},
  {"id":"pedsa2-3-6","src":"p2","num":"3.6","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":16,"stem":"Two unaffected parents have a child with cystic fibrosis. What is the risk that their next child is affected?","options":["1 in 2","1 in 3","1 in 4","2 in 3","Negligible"],"answer":2,"keyLetter":"C","explanation":"Autosomal recessive: both parents are carriers, so each pregnancy carries a 1 in 4 risk of being affected and a 2 in 3 chance that an UNAFFECTED sibling is a carrier — a favourite second half to this question."},
  {"id":"pedsa2-3-7","src":"p2","num":"3.7","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":17,"stem":"Which pattern best describes X-linked recessive inheritance?","options":["Affected males, carrier females, no male-to-male transmission, affected boys are related through the mother","Affected females only","Male-to-male transmission is typical","Every generation is affected in both sexes equally","Only maternal transmission to all offspring of both sexes"],"answer":0,"keyLetter":"A","explanation":"Classic examples are Duchenne muscular dystrophy, haemophilia A and B, and G6PD deficiency. Carrier mothers pass the gene to half their sons (affected) and half their daughters (carriers); an affected father has no affected sons but all carrier daughters."},
  {"id":"pedsa2-3-8","src":"p2","num":"3.8","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":17,"stem":"A family has a disorder transmitted only by affected mothers to all of their children, both boys and girls. What is the inheritance?","options":["Autosomal dominant","X-linked recessive","MITOCHONDRIAL","Autosomal recessive","Imprinting defect"],"answer":2,"keyLetter":"C","explanation":"Mitochondria are inherited exclusively from the mother. Variable severity between siblings is explained by heteroplasmy — the proportion of abnormal mitochondria differs between cells and individuals."},
  {"id":"pedsa2-3-9","src":"p2","num":"3.9","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":18,"stem":"A boy has learning difficulties, a long face with large ears, macro-orchidism after puberty and a family history of affected male relatives on the mother's side. What is the most likely diagnosis?","options":["Down syndrome","Fragile X syndrome","Klinefelter syndrome","Prader–Willi syndrome","Williams syndrome"],"answer":1,"keyLetter":"B","explanation":"Fragile X is the commonest inherited cause of learning disability, caused by a trinucleotide (CGG) repeat expansion in FMR1. It shows anticipation, and carrier females may be mildly affected."},
  {"id":"pedsa2-3-10","src":"p2","num":"3.10","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":18,"stem":"Which condition is an example of a multifactorial (polygenic) trait rather than single-gene inheritance?","options":["Cystic fibrosis","Achondroplasia","Neural tube defects","Haemophilia A","Duchenne muscular dystrophy"],"answer":2,"keyLetter":"C","explanation":"Multifactorial traits — neural tube defects, cleft lip and palate, congenital heart disease, pyloric stenosis, developmental dysplasia of the hip — result from genetic susceptibility plus environmental factors, and recurrence risks are given empirically, not by Mendelian ratios."},
  {"id":"pedsa2-3-11","src":"p2","num":"3.11","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":19,"stem":"A newborn has a single palmar crease, hypotonia, upslanting palpebral fissures and a flat occiput. Which investigations should be arranged?","options":["Karyotype (or rapid molecular test) and echocardiography","Karyotype only","MRI brain and EEG","Sweat test and chest X-ray","No investigations — the diagnosis is clinical"],"answer":0,"keyLetter":"A","explanation":"Down syndrome is suspected clinically but must be confirmed cytogenetically — which also identifies translocation cases needing parental testing. Echocardiography is essential because heart disease may be present without a murmur."},
  {"id":"pedsa2-3-12","src":"p2","num":"3.12","kind":"sba","block":"Block 3 · Genetics 12 QUESTIONS","page":19,"stem":"Which statement about genetic counselling is correct?","options":["It should direct parents to a particular reproductive decision","It provides accurate risk information non-directively so the family can make its own decision","It is only offered after a second affected child","Carrier testing of children for adult-onset conditions is routine","A three-generation family tree is rarely useful"],"answer":1,"keyLetter":"B","explanation":"Counselling is non-directive, based on an accurate diagnosis and a detailed three-generation pedigree. Predictive testing of children for adult-onset conditions is generally deferred so they can decide for themselves."},
  {"id":"pedsa2-4-1","src":"p2","num":"4.1","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":20,"stem":"What is the commonest cause of anaemia in childhood worldwide?","options":["Thalassaemia","Iron deficiency","Sickle cell disease","Aplastic anaemia","Folate deficiency"],"answer":1,"keyLetter":"B","explanation":"Iron deficiency — from inadequate intake (prolonged cow's milk, delayed weaning), malabsorption or blood loss. The film shows a microcytic, hypochromic picture."},
  {"id":"pedsa2-4-2","src":"p2","num":"4.2","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":20,"stem":"A 2-year-old has haemoglobin 8 g/dL with MCV 62 fL, low ferritin and a diet of 1.5 litres of cow's milk a day. What is the correct management?","options":["Blood transfusion","Dietary advice plus oral iron, continued for about 3 months after the haemoglobin normalises","Intramuscular iron immediately","Bone marrow examination","Iron for 2 weeks only"],"answer":1,"keyLetter":"B","explanation":"Oral iron is continued well beyond correction of the haemoglobin to replenish stores. Excessive cow's milk is the classic cause — it is low in iron and displaces iron-rich foods. Transfusion is not needed in a well child."},
  {"id":"pedsa2-4-3","src":"p2","num":"4.3","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":21,"stem":"Which combination best distinguishes β-thalassaemia trait from iron deficiency?","options":["Both have low ferritin","Thalassaemia trait: NORMAL or high ferritin, disproportionately low MCV for the degree of anaemia, raised HbA₂","Iron deficiency has a raised HbA₂","Thalassaemia trait responds to oral iron","Both show target cells only in iron deficiency"],"answer":1,"keyLetter":"B","explanation":"Giving iron to a child with thalassaemia trait is useless and potentially harmful. Check ferritin before treating a microcytic anaemia, and confirm the trait with haemoglobin electrophoresis (raised HbA₂)."},
  {"id":"pedsa2-4-4","src":"p2","num":"4.4","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":21,"stem":"A child with β-thalassaemia major on regular transfusions is at greatest long-term risk from which complication?","options":["Iron overload affecting heart, liver and endocrine organs","Vitamin C toxicity","Folate excess","Hypersplenism from transfusion","Renal stones"],"answer":0,"keyLetter":"A","explanation":"Regular transfusion prevents the anaemia and bone marrow expansion, but iron accumulates and causes cardiac failure, cirrhosis, diabetes and pubertal failure. Iron chelation is therefore essential, and cardiac disease is the usual cause of death when chelation fails."},
  {"id":"pedsa2-4-5","src":"p2","num":"4.5","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":22,"stem":"A 4-year-old Egyptian boy becomes acutely pale and jaundiced with dark urine two days after eating fava beans. Which is the most likely diagnosis?","options":["Hereditary spherocytosis","G6PD deficiency","Autoimmune haemolytic anaemia","Iron deficiency","Aplastic crisis"],"answer":1,"keyLetter":"B","explanation":"G6PD deficiency is X-linked and triggered by fava beans, infection and oxidant drugs (sulphonamides, quinolones, nitrofurantoin, primaquine, naphthalene mothballs). The film may show bite cells and Heinz bodies; the enzyme level should be checked after the acute episode, as it may be falsely normal during haemolysis when young red cells predominate."},
  {"id":"pedsa2-4-6","src":"p2","num":"4.6","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":22,"stem":"Which statement about hereditary spherocytosis is correct?","options":["It is autosomal recessive in most families","It is usually autosomal dominant and causes anaemia, jaundice, splenomegaly and gallstones","Splenectomy is contraindicated","Aplastic crisis is caused by rotavirus","The blood film is normal"],"answer":1,"keyLetter":"B","explanation":"Usually autosomal dominant, from red cell membrane protein defects. Parvovirus B19 causes aplastic crisis; folic acid is given; splenectomy is considered in severe disease, with vaccination and penicillin prophylaxis beforehand."},
  {"id":"pedsa2-4-7","src":"p2","num":"4.7","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":23,"stem":"A 3-year-old with sickle cell disease has a rapidly enlarging spleen, pallor and shock with a falling haemoglobin. What is the diagnosis?","options":["Aplastic crisis","Acute splenic sequestration","Vaso-occlusive crisis","Acute chest syndrome","Haemolytic crisis"],"answer":1,"keyLetter":"B","explanation":"Splenic sequestration — blood pools in the spleen, causing profound anaemia and hypovolaemic shock. Treatment is urgent transfusion. An aplastic crisis (parvovirus B19) gives anaemia with a LOW reticulocyte count and no splenomegaly."},
  {"id":"pedsa2-4-8","src":"p2","num":"4.8","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":23,"stem":"Which measures reduce mortality in young children with sickle cell disease?","options":["Penicillin prophylaxis and pneumococcal vaccination","Iron supplementation","Regular aspirin","Long-term corticosteroids","Fluid restriction"],"answer":0,"keyLetter":"A","explanation":"Functional hyposplenism makes encapsulated organisms lethal, so daily penicillin and full vaccination are central. Hydroxycarbamide reduces crises by raising HbF; folic acid is given; iron is not indicated unless deficiency is proven."},
  {"id":"pedsa2-4-9","src":"p2","num":"4.9","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":24,"stem":"A 5-year-old has a 2-day history of widespread petechiae and bruising, 2 weeks after a viral illness. He is otherwise well. Platelets 12 × 10⁹/L, haemoglobin and white cells normal. What is the most likely diagnosis?","options":["Acute lymphoblastic leukaemia","Immune thrombocytopenic purpura","Haemophilia A","Henoch–Schönlein purpura","Disseminated intravascular coagulation"],"answer":1,"keyLetter":"B","explanation":"ITP: isolated thrombocytopenia in a well child after a viral illness. Most cases are self-limiting and managed with observation; treatment is reserved for significant bleeding. Anaemia, neutropenia, bone pain or hepatosplenomegaly would point to leukaemia and demand a marrow."},
  {"id":"pedsa2-4-10","src":"p2","num":"4.10","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":24,"stem":"A boy has a prolonged APTT with a normal prothrombin time and normal platelets, and bled into a knee joint after a minor injury. What is the most likely diagnosis?","options":["Von Willebrand disease","Haemophilia A or B","Vitamin K deficiency","Immune thrombocytopenic purpura","Liver failure"],"answer":1,"keyLetter":"B","explanation":"Isolated APTT prolongation with haemarthrosis in a boy = haemophilia (factor VIII or IX deficiency), X-linked recessive. Treatment is factor replacement; avoid intramuscular injections, aspirin and NSAIDs. Von Willebrand disease more typically causes mucocutaneous bleeding."},
  {"id":"pedsa2-4-11","src":"p2","num":"4.11","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":25,"stem":"Which coagulation screen pattern fits vitamin K deficiency bleeding of the newborn?","options":["Prolonged PT with normal APTT and normal platelets, correcting with vitamin K","Normal PT with prolonged APTT","Low platelets alone","Prolonged bleeding time only","Normal screen"],"answer":0,"keyLetter":"A","explanation":"Vitamin K-dependent factors are II, VII, IX and X; factor VII has the shortest half-life, so the PT rises first. Severe deficiency prolongs both. Intramuscular vitamin K at birth prevents it, and exclusively breastfed babies are at greatest risk."},
  {"id":"pedsa2-4-12","src":"p2","num":"4.12","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":25,"stem":"A child with meningococcal sepsis has bleeding from venepuncture sites, low platelets, prolonged PT and APTT, low fibrinogen and raised D-dimers. What is the diagnosis?","options":["Immune thrombocytopenic purpura","Disseminated intravascular coagulation","Haemolytic uraemic syndrome","Haemophilia","Von Willebrand disease"],"answer":1,"keyLetter":"B","explanation":"DIC — consumption of platelets and clotting factors with fibrinolysis. Treat the underlying cause and support with fresh frozen plasma, cryoprecipitate and platelets. In HUS the clotting screen is NORMAL."},
  {"id":"pedsa2-4-13","src":"p2","num":"4.13","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":26,"stem":"Which feature in a child with purpura most strongly suggests a diagnosis OTHER than immune thrombocytopenic purpura?","options":["Recent viral illness","Hepatosplenomegaly, lymphadenopathy and bone pain","Petechiae over the trunk","Normal haemoglobin","Age 4 years"],"answer":1,"keyLetter":"B","explanation":"Those features mean marrow infiltration — leukaemia. ITP is an isolated thrombocytopenia in an otherwise well child; anything more requires bone marrow examination."},
  {"id":"pedsa2-4-14","src":"p2","num":"4.14","kind":"sba","block":"Block 4 · Haematology 14 QUESTIONS","page":26,"stem":"A pale 10-month-old has haemoglobin 6 g/dL, a very low reticulocyte count, normal platelets and white cells, and no hepatosplenomegaly. What does the low reticulocyte count indicate?","options":["Active haemolysis","Failure of red cell production","Acute blood loss","Hypersplenism","Iron overload"],"answer":1,"keyLetter":"B","explanation":"The reticulocyte count is the single most useful discriminator: HIGH = haemolysis or blood loss; LOW = reduced production (red cell aplasia, marrow failure, iron deficiency, chronic disease). This picture fits pure red cell aplasia."},
  {"id":"pedsa2-5-1","src":"p2","num":"5.1","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":27,"stem":"Which sign is the most SPECIFIC indicator of respiratory illness in a child?","options":["Tachypnoea","Increased work of breathing","Fever","Tachycardia","Vomiting"],"answer":1,"keyLetter":"B","explanation":"Tachypnoea is the most SENSITIVE sign of illness but is not specific — it occurs in acidosis, sepsis and heart failure. Increased work of breathing is what localises the problem to the chest."},
  {"id":"pedsa2-5-2","src":"p2","num":"5.2","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":27,"stem":"Why does obstruction OUTSIDE the thorax cause inspiratory stridor?","options":["Because expiration is passive","Because negative intrapleural pressure on inspiration collapses the extrathoracic airway while dilating intrathoracic airways","Because the trachea is rigid","Because of increased lung compliance","Because of bronchospasm"],"answer":1,"keyLetter":"B","explanation":"Upper (extrathoracic) obstruction bites on the way IN → stridor. Lower (intrathoracic) obstruction bites on the way OUT → wheeze."},
  {"id":"pedsa2-5-3","src":"p2","num":"5.3","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":28,"stem":"Which is NOT a sign of impending respiratory failure?","options":["Cyanosis or persistent grunting","Reduced saturation despite oxygen","Rising pCO₂","Exhaustion and reduced conscious level","Audible wheeze"],"answer":4,"keyLetter":"E","explanation":"Wheeze reflects airway narrowing, not failure — and a SILENT chest is the ominous sign. The four warnings are cyanosis/grunting, desaturation despite oxygen, RISING pCO₂, and exhaustion or confusion."},
  {"id":"pedsa2-5-4","src":"p2","num":"5.4","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":28,"stem":"A 2-year-old has a barking cough and inspiratory stridor that is worse at night, following two days of coryza. He is alert with mild recession. What is the treatment?","options":["A single dose of oral dexamethasone","Intravenous antibiotics","Nebulised salbutamol","Immediate intubation","Throat examination and swab"],"answer":0,"keyLetter":"A","explanation":"Croup (laryngotracheobronchitis), 6 months–6 years, parainfluenza. Mild or moderate disease responds to a single dose of oral dexamethasone; severe disease gets nebulised adrenaline with observation for 2–3 hours because of rebound."},
  {"id":"pedsa2-5-5","src":"p2","num":"5.5","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":29,"stem":"Which feature most strongly favours epiglottitis over croup?","options":["Barking cough","Onset over hours with drooling, a muffled voice and NO cough","Symptoms worse at night","Preceding coryza for 2 days","Loud harsh stridor"],"answer":1,"keyLetter":"B","explanation":"Epiglottitis: hours not days, toxic, drooling, muffled voice, absent cough, SOFT stridor. Do not examine the throat or lie the child down — call for anaesthetic, paediatric and ENT help to secure the airway first."},
  {"id":"pedsa2-5-6","src":"p2","num":"5.6","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":29,"stem":"A 4-week-old has intermittent stridor that is worse when lying flat and when crying, but he feeds well and is thriving. What is the most likely diagnosis?","options":["Croup","Laryngomalacia","Vascular ring","Subglottic stenosis","Inhaled foreign body"],"answer":1,"keyLetter":"B","explanation":"Laryngomalacia — the commonest cause of persistent stridor in infancy; typically presents at about 4 weeks, worse supine, and resolves by about 2 years. Faltering growth or severe obstruction would prompt laryngoscopy."},
  {"id":"pedsa2-5-7","src":"p2","num":"5.7","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":29,"stem":"Which organism causes about 80% of bronchiolitis?","options":["Parainfluenza virus","Respiratory syncytial virus","Rhinovirus","Mycoplasma pneumoniae","Adenovirus"],"answer":1,"keyLetter":"B","explanation":"RSV. Bronchiolitis affects infants 1–9 months, with coryza then a dry wheezy cough, feeding difficulty, fine end-inspiratory crackles and, in the youngest, APNOEA."},
  {"id":"pedsa2-5-8","src":"p2","num":"5.8","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":30,"stem":"Which is an indication for admission in bronchiolitis?","options":["Any wheeze","Apnoea, saturation below 92%, intake under 70% of normal, or respiratory rate over 70","Cough lasting more than 3 days","Temperature 38 °C","Parental anxiety alone"],"answer":1,"keyLetter":"B","explanation":"Management is supportive — humidified oxygen, fluids, monitoring. Bronchodilators, steroids, antibiotics, mist and hypertonic saline are of no proven benefit."},
  {"id":"pedsa2-5-9","src":"p2","num":"5.9","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":30,"stem":"In a child over 5 years with pneumonia, which organism should be considered in addition to Streptococcus pneumoniae?","options":["Mycoplasma pneumoniae","Group B streptococcus","Listeria","Pseudomonas","RSV"],"answer":0,"keyLetter":"A","explanation":"Over 5 years, think Mycoplasma — a longer prodrome, headache, and sometimes extrapulmonary features. A macrolide is used. Respiratory rate is the most sensitive sign of pneumonia, and oral antibiotics are as effective as IV in mild disease."},
  {"id":"pedsa2-5-10","src":"p2","num":"5.10","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":31,"stem":"A child with pneumonia remains febrile after 48 hours of appropriate antibiotics, with a stony dull percussion note at the base. What is the most likely complication?","options":["Asthma","Empyema","Pneumothorax","Bronchiolitis","Pulmonary embolism"],"answer":1,"keyLetter":"B","explanation":"Persistent fever at 48 hours = effusion or empyema until imaged. Ultrasound guides drainage; a chest drain with fibrinolytics may be required."},
  {"id":"pedsa2-5-11","src":"p2","num":"5.11","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":31,"stem":"A 3-month-old has paroxysms of coughing followed by vomiting and episodes of apnoea. The white cell count shows a lymphocytosis of 18 × 10⁹/L. What is the diagnosis?","options":["Bronchiolitis","Pertussis","Asthma","Cystic fibrosis","Croup"],"answer":1,"keyLetter":"B","explanation":"Pertussis: catarrhal phase, then paroxysmal coughing with whoop (often absent in infants), tussive vomiting and apnoea, with a lymphocytosis >15 × 10⁹/L. A macrolide only alters the course if given in the CATARRHAL phase, but is still given to reduce infectivity."},
  {"id":"pedsa2-5-12","src":"p2","num":"5.12","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":32,"stem":"Which feature best supports a diagnosis of asthma in a 6-year-old with recurrent wheeze?","options":["Wheeze only with colds and no symptoms in between","Symptoms at night and in the early morning, with atopy and a family history","Wet cough with clubbing","Faltering growth","Stridor"],"answer":1,"keyLetter":"B","explanation":"Interval symptoms, nocturnal and early-morning cough or wheeze, and atopy support asthma. Clubbing, a wet cough and faltering growth are NEVER asthma — they mean suppurative lung disease."},
  {"id":"pedsa2-5-13","src":"p2","num":"5.13","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":32,"stem":"Which spirometry result supports asthma?","options":["FEV₁:FVC below 80% with reversibility of FEV₁ greater than 12% after a bronchodilator","A restrictive pattern with normal ratio","Normal spirometry excludes asthma","Reduced FVC with normal FEV₁","Reversibility of less than 5%"],"answer":0,"keyLetter":"A","explanation":"And the trap: normal spirometry between attacks does NOT exclude asthma."},
  {"id":"pedsa2-5-14","src":"p2","num":"5.14","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":32,"stem":"Which statement about asthma treatment is correct?","options":["A long-acting beta agonist may be used alone if symptoms are mild","A long-acting beta agonist must NEVER be given without an inhaled corticosteroid","Short-acting beta agonists are used as maintenance monotherapy","Leukotriene receptor antagonists are contraindicated in children","Inhaler technique rarely matters"],"answer":1,"keyLetter":"B","explanation":"LABA never without ICS; SABA never alone as maintenance. In under-fives the usual add-on is a leukotriene receptor antagonist. Always check adherence, inhaler technique and trigger avoidance before escalating."},
  {"id":"pedsa2-5-15","src":"p2","num":"5.15","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":33,"stem":"Which combination defines a LIFE-THREATENING asthma attack?","options":["Wheeze with a peak flow of 60% predicted","Silent chest, poor respiratory effort, exhaustion or confusion, saturation below 92%","Able to speak in sentences with mild recession","Cough only at night","Heart rate 110"],"answer":1,"keyLetter":"B","explanation":"Treat with oxygen, nebulised bronchodilators with ipratropium, systemic steroids, IV therapies and intensive care involvement. Blood gases are often normal until the child is in extremis, so do not be reassured by them."},
  {"id":"pedsa2-5-16","src":"p2","num":"5.16","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":33,"stem":"Which investigation confirms cystic fibrosis?","options":["Chest X-ray","Sweat chloride greater than 60 mmol/L, with CFTR mutation analysis","Spirometry with reversibility","Exhaled nitric oxide","Faecal calprotectin"],"answer":1,"keyLetter":"B","explanation":"CF is autosomal recessive, gene on chromosome 7, commonest mutation Phe508del. Meconium ileus occurs in 10–20%; other clues are nasal polyps, rectal prolapse, malabsorption with bulky offensive stools, and clubbing."},
  {"id":"pedsa2-5-17","src":"p2","num":"5.17","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":34,"stem":"Which best describes the management of cystic fibrosis?","options":["Antibiotics only when symptomatic","Physiotherapy, pancreatic enzymes with fat-soluble vitamins, high-calorie diet, aggressive antibiotic therapy and CFTR modulators","Low-fat diet and fluid restriction","Inhaled corticosteroids alone","Avoidance of exercise"],"answer":1,"keyLetter":"B","explanation":"Care is multidisciplinary and proactive. CFTR modulators have changed the outlook substantially for eligible genotypes."},
  {"id":"pedsa2-5-18","src":"p2","num":"5.18","kind":"sba","block":"Block 5 · Respiratory 18 QUESTIONS","page":34,"stem":"A 7-year-old has a chronic wet cough, recurrent sinusitis, bronchiectasis and dextrocardia on the chest X-ray. What is the diagnosis?","options":["Cystic fibrosis","Primary ciliary dyskinesia (Kartagener syndrome)","Asthma","Immunodeficiency","Inhaled foreign body"],"answer":1,"keyLetter":"B","explanation":"About 50% of children with primary ciliary dyskinesia have Kartagener syndrome — situs inversus + sinusitis + bronchiectasis. Suspect it with a persistent wet cough and chronic ear and sinus disease."},
  {"id":"pedsa2-6-1","src":"p2","num":"6.1","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":35,"stem":"What is the commonest congenital cardiac malformation?","options":["Atrial septal defect","Ventricular septal defect","Persistent ductus arteriosus","Tetralogy of Fallot","Pulmonary stenosis"],"answer":1,"keyLetter":"B","explanation":"VSD accounts for about 30%, then PDA 12%, ASD 7%, PS 7%, ToF 5%, TGA 5%, AS 5%, coarctation 5%, AVSD 2% — the nine commonest lesions make up 80% of all congenital heart disease."},
  {"id":"pedsa2-6-2","src":"p2","num":"6.2","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":35,"stem":"Which of the following is NOT a hallmark of an innocent murmur?","options":["Asymptomatic child","Soft blowing quality","Diastolic component","Left sternal edge","Normal heart sounds"],"answer":2,"keyLetter":"C","explanation":"The five Ss: aSymptomatic, Soft, Systolic only, left Sternal edge, normal Sounds — with no thrill and no radiation. Any diastolic murmur is pathological."},
  {"id":"pedsa2-6-3","src":"p2","num":"6.3","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":36,"stem":"Which three assessments must accompany every examination for a murmur?","options":["Femoral pulses, oxygen saturations and blood pressure","Chest X-ray, ECG and echocardiogram","Height, weight and head circumference","Full blood count, CRP and blood culture","Urinalysis, ECG and glucose"],"answer":0,"keyLetter":"A","explanation":"Missing an absent femoral pulse or a low saturation is how duct-dependent lesions are missed."},
  {"id":"pedsa2-6-4","src":"p2","num":"6.4","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":36,"stem":"A 5-year-old has an ejection systolic murmur at the upper left sternal edge and a second heart sound that is widely split and does not vary with respiration. What is the diagnosis?","options":["Innocent murmur","Atrial septal defect","Ventricular septal defect","Pulmonary stenosis","Persistent ductus arteriosus"],"answer":1,"keyLetter":"B","explanation":"FIXED splitting of the second sound is the signature of an ASD — the right ventricle carries a constant extra volume load, so the respiratory variation is abolished. The murmur itself is flow across the pulmonary valve, not across the defect."},
  {"id":"pedsa2-6-5","src":"p2","num":"6.5","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":37,"stem":"A superior QRS axis (mainly negative in aVF) in a child with an atrial septal defect suggests which lesion?","options":["Secundum ASD","Partial atrioventricular septal defect","Sinus venosus defect only","Patent foramen ovale","Ventricular septal defect"],"answer":1,"keyLetter":"B","explanation":"The AVSD sits in the middle of the heart where the atrioventricular node is, displacing conduction superiorly. There is also an apical pansystolic murmur from the regurgitant left AV valve, and treatment is surgery at about 3 years rather than a device."},
  {"id":"pedsa2-6-6","src":"p2","num":"6.6","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":37,"stem":"A loud pansystolic murmur at the lower left sternal edge in a thriving 4-month-old with a quiet P2 indicates:","options":["A large VSD needing surgery","A small VSD that will probably close spontaneously","Pulmonary hypertension","An innocent murmur","Aortic stenosis"],"answer":1,"keyLetter":"B","explanation":"The louder the murmur, the smaller the hole. Small VSDs make up 80–90% of cases, close spontaneously, and need only good dental hygiene — no restriction and no surgery."},
  {"id":"pedsa2-6-7","src":"p2","num":"6.7","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":38,"stem":"Which set of findings indicates a LARGE ventricular septal defect?","options":["Loud pansystolic murmur, normal chest X-ray, normal ECG","Soft or absent murmur, loud P2, active precordium, apical mid-diastolic murmur, cardiomegaly and pulmonary oedema","Continuous murmur below the left clavicle","Ejection systolic murmur with a carotid thrill","Fixed split second sound"],"answer":1,"keyLetter":"B","explanation":"Treatment is diuretics, captopril and extra calories, then surgery at 3–6 months — to treat heart failure and to prevent irreversible pulmonary vascular disease."},
  {"id":"pedsa2-6-8","src":"p2","num":"6.8","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":38,"stem":"Why is a persistent ductus arteriosus murmur continuous?","options":["Because flow is turbulent only in systole","Because pulmonary artery pressure is lower than aortic pressure throughout the cardiac cycle","Because the duct closes in diastole","Because of associated aortic regurgitation","Because the murmur is innocent"],"answer":1,"keyLetter":"B","explanation":"Hence a continuous \"machinery\" murmur beneath the left clavicle, with bounding pulses if large. Closure with a coil or device at about 1 year abolishes the lifelong risk of endocarditis."},
  {"id":"pedsa2-6-9","src":"p2","num":"6.9","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":39,"stem":"A neonate is deeply cyanosed on day 2 with NO murmur. The chest X-ray shows an \"egg on side\" with a narrow mediastinum. What is the diagnosis and immediate management?","options":["Tetralogy of Fallot — beta blocker","Transposition of the great arteries — prostaglandin and consideration of balloon atrial septostomy","Coarctation — surgery","Total anomalous pulmonary venous drainage — diuretics","Persistent pulmonary hypertension — nitric oxide alone"],"answer":1,"keyLetter":"B","explanation":"In TGA the circulations run in parallel, so survival depends on mixing. Prostaglandin keeps the duct open; balloon atrial septostomy is needed in about 20%; the arterial switch is performed in the neonatal period."},
  {"id":"pedsa2-6-10","src":"p2","num":"6.10","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":39,"stem":"Which is NOT one of the four features of tetralogy of Fallot?","options":["Large ventricular septal defect","Overriding aorta","Subpulmonary stenosis","Right ventricular hypertrophy","Atrial septal defect"],"answer":4,"keyLetter":"E","explanation":"The right ventricular outflow obstruction is the driver: it forces blood right to left across the VSD. The chest X-ray shows a small boot-shaped heart with oligaemic lung fields."},
  {"id":"pedsa2-6-11","src":"p2","num":"6.11","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":40,"stem":"A 9-month-old with tetralogy of Fallot has a hypercyanotic spell lasting 20 minutes. Which treatment combination is correct?","options":["Morphine, IV propranolol, IV volume and bicarbonate","Nebulised salbutamol and oral prednisolone","Adenosine and cardioversion","Furosemide and captopril","Immediate arterial switch operation"],"answer":0,"keyLetter":"A","explanation":"Spells are usually self-limiting and followed by sleep, but beyond about 15 minutes they must be treated — untreated they cause myocardial infarction, stroke and death. Note that the murmur becomes quieter or disappears during a spell."},
  {"id":"pedsa2-6-12","src":"p2","num":"6.12","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":40,"stem":"A 12-year-old with a large unrepaired VSD is now cyanosed with no murmur and signs of right heart failure. What has happened?","options":["The defect has enlarged","Eisenmenger syndrome — pulmonary vascular disease has reversed the shunt","Infective endocarditis","Rheumatic fever","Aortic stenosis has developed"],"answer":1,"keyLetter":"B","explanation":"Years of high pulmonary blood flow thicken the pulmonary arteries; the shunt reverses at about 10–15 years. Prevention — early closure of large shunts — is the only real treatment."},
  {"id":"pedsa2-6-13","src":"p2","num":"6.13","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":41,"stem":"Which finding distinguishes aortic stenosis from pulmonary stenosis?","options":["An ejection click","A carotid thrill","An ejection systolic murmur","A normal chest X-ray","Post-stenotic dilatation"],"answer":1,"keyLetter":"B","explanation":"Aortic stenosis: upper RIGHT sternal edge, radiates to the neck, carotid thrill ALWAYS, slow-rising small-volume pulse, soft delayed A2. Pulmonary stenosis: upper LEFT sternal edge, no carotid thrill. Intervention when the gradient exceeds 64 mmHg."},
  {"id":"pedsa2-6-14","src":"p2","num":"6.14","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":41,"stem":"A previously well term baby collapses at 48 hours with grey mottled skin, absent femoral pulses and a pH of 7.05. What is the single most important immediate treatment?","options":["Prostaglandin E infusion","Nebulised adrenaline","Oral propranolol","Furosemide","Adenosine"],"answer":0,"keyLetter":"A","explanation":"Duct-dependent coarctation — normal on day 1, collapse when the duct closes. Resuscitate, give prostaglandin at the earliest opportunity, cover for sepsis, and refer to a cardiac centre for early surgery."},
  {"id":"pedsa2-6-15","src":"p2","num":"6.15","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":41,"stem":"Which findings suggest ADULT-type coarctation of the aorta?","options":["Absent femoral pulses with shock in the neonate","Right arm hypertension, radio-femoral delay, rib notching and a \"3 sign\"","Fixed split second heart sound","Continuous murmur below the left clavicle","Egg-on-side heart"],"answer":1,"keyLetter":"B","explanation":"This lesion is NOT duct dependent and worsens over years; the leg pulse is delayed because blood arrives through chest wall collaterals. Treatment is stent insertion or surgery."},
  {"id":"pedsa2-6-16","src":"p2","num":"6.16","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":42,"stem":"An infant has a narrow complex tachycardia at 280 beats/min with poor perfusion. Vagal manoeuvres have failed and IV access is in place. What is next?","options":["Intravenous adenosine","Immediate DC shock at 4 J/kg","Oral digoxin","Intravenous amiodarone as first line","Observation"],"answer":0,"keyLetter":"A","explanation":"Ladder: circulatory and respiratory support → vagal manoeuvres (successful in about 80%) → IV adenosine in incrementally increasing doses → synchronised DC cardioversion 0.5–2 J/kg. Maintenance is with flecainide or sotalol; digoxin only if there is no delta wave."},
  {"id":"pedsa2-6-17","src":"p2","num":"6.17","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":42,"stem":"Which is a MINOR criterion in the Jones criteria for rheumatic fever?","options":["Carditis","Migratory polyarthritis","Prolonged P-R interval","Erythema marginatum","Subcutaneous nodules"],"answer":2,"keyLetter":"C","explanation":"Minor criteria are FRPP — Fever, Raised acute-phase reactants, Polyarthralgia, Prolonged P-R interval. Diagnosis needs 2 major, or 1 major + 2 minor, PLUS evidence of preceding streptococcal infection. Secondary prophylaxis is monthly benzathine penicillin for 10 years or until age 21, whichever is longer."},
  {"id":"pedsa2-6-18","src":"p2","num":"6.18","kind":"sba","block":"Block 6 · Cardiac Disorders 18 QUESTIONS","page":43,"stem":"Which statement about infective endocarditis in children is correct?","options":["A normal echocardiogram excludes the diagnosis","Multiple blood cultures must be taken before antibiotics; treatment is 6 weeks of IV penicillin plus an aminoglycoside","Routine antibiotic prophylaxis before dental treatment is recommended for all cardiac lesions","Staphylococcus epidermidis is the commonest organism","Peripheral stigmata are reliable for diagnosis"],"answer":1,"keyLetter":"B","explanation":"The commonest organism is α-haemolytic streptococcus (Strep. viridans). Echocardiography can confirm but never exclude, the classical stigmata are unreliable, and prevention is good dental hygiene — routine antibiotic prophylaxis is no longer recommended for most conditions."},
  {"id":"pedsa2-7-1","src":"p2","num":"7.1","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":44,"stem":"Which statement about plasma creatinine in children is correct?","options":["The normal range is the same at all ages","The normal range RISES through childhood with increasing muscle mass and height","It rises before urea in acute kidney injury","It is unaffected by muscle mass","It is the earliest marker of chronic kidney disease"],"answer":1,"keyLetter":"B","explanation":"Urea rises before creatinine but is less specific. Urinary protein loss occurs before the GFR falls in chronic kidney disease. eGFR = 31 × height (cm) ÷ creatinine."},
  {"id":"pedsa2-7-2","src":"p2","num":"7.2","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":44,"stem":"What is the GFR of a term newborn, corrected for surface area?","options":["80–120 mL/min per 1.73 m²","20–30 mL/min per 1.73 m², rising to adult values by 1–2 years","Identical to the adult value at birth","Zero for the first week","50% of adult values at 28 weeks' gestation"],"answer":1,"keyLetter":"B","explanation":"At 28 weeks' gestation the GFR is only 10% of the term infant's, which is why renally excreted drugs need such care in the preterm."},
  {"id":"pedsa2-7-3","src":"p2","num":"7.3","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":45,"stem":"Which investigation is used to detect renal SCARS?","options":["MAG3 scan","DMSA scan","MCUG","Plain abdominal X-ray","CT"],"answer":1,"keyLetter":"B","explanation":"DMSA = static cortical scan for damage; MAG3 = dynamic scan for drainage (often with furosemide); MCUG = reflux and urethral valves. A DMSA must be deferred at least 2–3 months after a UTI or transient inflammation is misread as scarring."},
  {"id":"pedsa2-7-4","src":"p2","num":"7.4","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":45,"stem":"Antenatal ultrasound shows bilateral hydronephrosis in a male fetus. What is the correct postnatal plan?","options":["Ultrasound at 4–6 weeks","Ultrasound within 48 hours of birth to exclude posterior urethral valves, then MCUG","No imaging unless symptomatic","DMSA in the first week","Immediate nephrectomy"],"answer":1,"keyLetter":"B","explanation":"All other antenatally detected anomalies have their scan delayed a few weeks, because the newborn is relatively oliguric in the first days and early scanning under-estimates dilatation."},
  {"id":"pedsa2-7-5","src":"p2","num":"7.5","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":46,"stem":"Which statement distinguishes multicystic dysplastic kidney from polycystic kidney disease?","options":["MCDK is a non-functioning kidney with ureteric atresia that usually involutes; PKD affects both kidneys with preserved function","MCDK always affects both kidneys","PKD never causes hypertension","MCDK requires nephrectomy in all cases","PKD is only diagnosed in adulthood"],"answer":0,"keyLetter":"A","explanation":"Half of multicystic dysplastic kidneys involute by 2 years. In ADPKD (1 in 1000) the childhood problem is hypertension, with extrarenal cysts, cerebral aneurysms and mitral valve prolapse."},
  {"id":"pedsa2-7-6","src":"p2","num":"7.6","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":46,"stem":"Bilateral renal agenesis leads to death in the newborn period principally because of:","options":["Renal failure","Pulmonary hypoplasia","Cardiac malformation","Hyperkalaemia","Limb deformity"],"answer":1,"keyLetter":"B","explanation":"Potter sequence: no fetal urine → oligohydramnios → fetal compression (Potter facies, limb deformities) and, critically, pulmonary hypoplasia — the lungs are what kill."},
  {"id":"pedsa2-7-7","src":"p2","num":"7.7","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":46,"stem":"Which statement about vesicoureteric reflux is correct?","options":["It is familial in 30–50% of first-degree relatives, and mild reflux often resolves with age","All grades require surgery","It never causes hypertension","It cannot occur temporarily after a UTI","Reflux nephropathy does not progress to chronic kidney disease"],"answer":0,"keyLetter":"A","explanation":"Severe reflux risks pyelonephritis, scarring (reflux nephropathy), CKD and up to 10% hypertension — but operating on MILD reflux has not been shown to reduce renal damage."},
  {"id":"pedsa2-7-8","src":"p2","num":"7.8","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":47,"stem":"A 7-month-old has a fever of 39 °C with vomiting and no focus on examination. What is the single most important investigation?","options":["Chest X-ray","Urine sample for microscopy and culture","Full blood count only","Abdominal ultrasound","Lumbar puncture in all cases"],"answer":1,"keyLetter":"B","explanation":"Test the urine of any infant with an unexplained fever above 38 °C. The commonest error in childhood UTI is failing to establish the diagnosis properly in the first place — and with it the chance to prevent renal damage."},
  {"id":"pedsa2-7-9","src":"p2","num":"7.9","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":47,"stem":"Which urine result is diagnostic of infection regardless of colony count?","options":["Any growth from a suprapubic aspirate","10³ CFU/mL from a bag sample","Leucocytes on microscopy","Nitrites alone on a bag sample","10⁴ CFU/mL from a clean catch"],"answer":0,"keyLetter":"A","explanation":"For a clean-catch or midstream sample the threshold is >10⁵ CFU/mL of a single organism (90% probability, 95% if repeated). Urinary white cells are not reliable — they lyse on storage and occur in other illness."},
  {"id":"pedsa2-7-10","src":"p2","num":"7.10","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":48,"stem":"A 10-week-old has a confirmed UTI. What is the correct management?","options":["Oral trimethoprim for 3 days at home","Immediate hospital referral with IV antibiotics for at least 5–7 days, then oral prophylaxis","Nitrofurantoin for 5 days","No antibiotics unless febrile","Await the DMSA result before treating"],"answer":1,"keyLetter":"B","explanation":"All infants under 3 months with a suspected UTI, and any seriously ill child, are referred to hospital. Over 3 months: upper UTI 7–10 days, cystitis 5 days orally."},
  {"id":"pedsa2-7-11","src":"p2","num":"7.11","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":48,"stem":"Which feature makes a UTI \"atypical\" and mandates further investigation?","options":["Fever of 38.5 °C","Failure to respond to suitable antibiotics within 48 hours, or a non-E. coli organism","Dysuria","A single previous UTI","Age 4 years"],"answer":1,"keyLetter":"B","explanation":"Atypical features: seriously ill or septicaemic, poor urine flow, abdominal or bladder mass, raised creatinine, no response in 48 hours, non-E. coli organism. Proteus also raises the possibility of stones because it splits urea and alkalinises urine."},
  {"id":"pedsa2-7-12","src":"p2","num":"7.12","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":49,"stem":"A 6-year-old girl is constantly damp with no dry intervals, day and night, since toilet training. What is the most likely cause?","options":["Detrusor instability","Ectopic ureter","Urinary tract infection","Constipation","Emotional upset"],"answer":1,"keyLetter":"B","explanation":"Constant dribbling with no dry periods = an ectopic ureter draining below the sphincter. Detrusor instability causes urgency with dry intervals; secondary enuresis after a period of dryness is most often emotional, but exclude UTI and diabetes."},
  {"id":"pedsa2-7-13","src":"p2","num":"7.13","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":49,"stem":"Which finding indicates GLOMERULAR rather than lower urinary tract haematuria?","options":["Red urine at the end of the stream","Brown urine with deformed red cells, red cell casts and proteinuria","Absence of proteinuria","Clots in the urine","Dysuria"],"answer":1,"keyLetter":"B","explanation":"Red cells deform passing through the basement membrane. Confirm haematuria on microscopy (>10 RBCs per high-power field) — rifampicin, beetroot and haemoglobinuria all discolour urine without red cells."},
  {"id":"pedsa2-7-14","src":"p2","num":"7.14","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":50,"stem":"A 4-year-old boy has periorbital oedema that is worst on waking, ascites, 4+ proteinuria, albumin 14 g/L, normal blood pressure, normal complement and normal renal function. What is the correct treatment?","options":["Renal biopsy first","Oral prednisolone 60 mg/m²/day for 4 weeks, then 40 mg/m² on alternate days","Furosemide alone","Cyclophosphamide","Antibiotics only"],"answer":1,"keyLetter":"B","explanation":"All five typical features are present, so this is steroid-sensitive nephrotic syndrome (85–90% of cases). Median time to protein-free urine is 11 days; biopsy only if there is no response after 4–6 weeks or if features are atypical."},
  {"id":"pedsa2-7-15","src":"p2","num":"7.15","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":50,"stem":"A child with nephrotic syndrome develops abdominal pain. Urinary sodium is 8 mmol/L and the haemoglobin is high. What does this indicate?","options":["Hypervolaemia — give more diuretic","HYPOVOLAEMIA — give IV 0.9% saline or albumin","Constipation","Appendicitis","Steroid side-effect"],"answer":1,"keyLetter":"B","explanation":"The child looks waterlogged but is intravascularly depleted: urinary sodium <10 mmol/L and a raised haematocrit are the clues. Untreated it risks thrombosis and shock; diuretics make it worse. Spontaneous pneumococcal peritonitis is the other cause of abdominal pain here."},
  {"id":"pedsa2-7-16","src":"p2","num":"7.16","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":51,"stem":"A 7-year-old has smoky brown urine, periorbital oedema, a blood pressure of 138/92 and reduced urine output 3 weeks after a sore throat. Which result would you expect?","options":["Low C3 that returns to normal in 3–4 weeks","Low C3 and low C4 persisting","Normal complement with raised IgA","Positive ANCA","Low platelets and fragmented red cells"],"answer":0,"keyLetter":"A","explanation":"Post-streptococcal glomerulonephritis — a type III immune-complex disease. Over 95% recover completely; persistently low complement is an indication for biopsy, and both C3 and C4 low suggests SLE."},
  {"id":"pedsa2-7-17","src":"p2","num":"7.17","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":51,"stem":"Which statement about Henoch–Schönlein purpura is correct?","options":["The platelet count is low","The purpura is palpable, distributed over the buttocks and extensor surfaces with sparing of the trunk, and over 80% have haematuria or proteinuria","It is commoner in girls","The rash is the last feature to appear","Renal involvement never requires follow-up"],"answer":1,"keyLetter":"B","explanation":"HSP is the commonest childhood systemic vasculitis: age 3–10 years, twice as common in boys, peaks in winter, often after a URTI. Watch for intussusception with abdominal pain, and follow up the urine and blood pressure."},
  {"id":"pedsa2-7-18","src":"p2","num":"7.18","kind":"sba","block":"Block 7 · Kidney and Urinary Tract 18 QUESTIONS","page":52,"stem":"A child with acute kidney injury has a potassium of 7.4 mmol/L with peaked T waves on the ECG. What is given FIRST?","options":["Calcium gluconate","Salbutamol nebuliser","Glucose and insulin","Calcium exchange resin","Dialysis"],"answer":0,"keyLetter":"A","explanation":"Calcium gluconate protects the myocardium when there are ECG changes — it does not lower the potassium. Then salbutamol and glucose/insulin shift potassium into cells, and resin or dialysis removes it. Prerenal failure is the commonest AKI in children; HUS and acute tubular necrosis are the commonest renal causes."},
  {"id":"pedsa2-8-1","src":"p2","num":"8.1","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":53,"stem":"Which headache feature is a RED FLAG for a space-occupying lesion?","options":["Headache present on waking that improves through the morning","Headache that is worse lying down and wakes the child at night","Bilateral pulsatile headache relieved by sleep","Headache with photophobia in a dark quiet room","Band-like constriction headache"],"answer":1,"keyLetter":"B","explanation":"Red flags: worse lying down or with coughing/straining, wakes the child, morning vomiting, and change in personality or school performance — plus growth failure, visual field defect, squint, torticollis, ataxia, bradycardia and papilloedema (a late sign)."},
  {"id":"pedsa2-8-2","src":"p2","num":"8.2","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":53,"stem":"A child with raised intracranial pressure has a squint and cannot abduct one eye. Which nerve is affected and what does it tell you?","options":["IIIrd nerve — the lesion is in the midbrain","VIth nerve — a FALSE localising sign","IVth nerve — cerebellar lesion","VIIth nerve — pontine lesion","IInd nerve — optic pathway lesion"],"answer":1,"keyLetter":"B","explanation":"The abducent nerve has a long intracranial course and is compressed wherever the lesion is. A VIIth nerve palsy, in contrast, does suggest a pontine lesion."},
  {"id":"pedsa2-8-3","src":"p2","num":"8.3","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":54,"stem":"A 13-year-old with migraine now has headache on 18 days a month and uses ibuprofen or a triptan four days a week. What is the diagnosis?","options":["Chronic tension-type headache","Medication overuse headache","Idiopathic intracranial hypertension","Cluster headache","Brain tumour"],"answer":1,"keyLetter":"B","explanation":"Rebound headache follows use of acute analgesia or triptans on more than 2 days a week; withdrawal of the drug resolves it in about 2 weeks."},
  {"id":"pedsa2-8-4","src":"p2","num":"8.4","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":54,"stem":"Which prophylactic drug for migraine is contraindicated in asthma?","options":["Topiramate","Propranolol","Pizotifen","Amitriptyline","Valproate"],"answer":1,"keyLetter":"B","explanation":"Beta blockade can precipitate bronchospasm. Alternatives include topiramate or valproate, pizotifen or amitriptyline, with attention to sleep, food, fluids and lifestyle."},
  {"id":"pedsa2-8-5","src":"p2","num":"8.5","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":55,"stem":"A 6-month-old has clusters of sudden flexion of the head and trunk followed by extension of the arms, 20–30 at a time, mostly on waking. He has stopped smiling at his mother. What is the diagnosis and treatment?","options":["Colic — reassurance","Infantile spasms (West syndrome) — vigabatrin or corticosteroids","Benign myoclonus — no treatment","Reflux — anti-reflux medication","Febrile seizures — antipyretics"],"answer":1,"keyLetter":"B","explanation":"Loss of social interaction is the key marker and spasms are commonly misdiagnosed as colic. The EEG shows hypsarrhythmia; there is a good initial response in about 70%, but relapse is common and most develop learning disability."},
  {"id":"pedsa2-8-6","src":"p2","num":"8.6","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":55,"stem":"Which epilepsy syndrome is characterised by brief staring episodes lasting under 30 seconds, provoked by hyperventilation, with 3 Hz spike-and-wave on EEG?","options":["Juvenile myoclonic epilepsy","Childhood absence epilepsy","Rolandic epilepsy","Lennox–Gastaut syndrome","Panayiotopoulos syndrome"],"answer":1,"keyLetter":"B","explanation":"Onset 4–12 years, two-thirds female, 80% remit in adolescence, and it accounts for only about 2% of childhood epilepsy. Provoke it in clinic by asking the child to blow on a windmill for 2–3 minutes."},
  {"id":"pedsa2-8-7","src":"p2","num":"8.7","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":56,"stem":"A 15-year-old drops her cereal bowl most mornings because of sudden jerks, and has had one generalised seizure shortly after waking. Which is correct?","options":["Juvenile myoclonic epilepsy — treatment is usually effective but lifelong","Childhood absence epilepsy — remission is usual","Rolandic epilepsy — no treatment needed","Non-epileptic attack disorder","Lennox–Gastaut syndrome"],"answer":0,"keyLetter":"A","explanation":"Myoclonus shortly after waking is the signature. Learning is unimpaired, response to treatment is good, but remission is unlikely — and carbamazepine would make it worse."},
  {"id":"pedsa2-8-8","src":"p2","num":"8.8","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":56,"stem":"Which investigation is recommended in ALL children presenting with seizures?","options":["MRI brain","12-lead ECG","Lumbar puncture","Metabolic screen","Sleep-deprived EEG"],"answer":1,"keyLetter":"B","explanation":"Because a missed long QT syndrome is an avoidable death. Imaging is not needed in clear-cut generalised syndromes such as childhood absence or rolandic epilepsy."},
  {"id":"pedsa2-8-9","src":"p2","num":"8.9","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":56,"stem":"A child has been convulsing for 6 minutes. There is no IV access. What is the first drug?","options":["Buccal midazolam or rectal diazepam","IV phenytoin","IM phenobarbitone","Thiopental","Oral levetiracetam"],"answer":0,"keyLetter":"A","explanation":"Treat at 5 minutes. With access: lorazepam. Without: buccal midazolam or rectal diazepam. Throughout — airway, high-flow oxygen and \"Don't Ever Forget Glucose\"."},
  {"id":"pedsa2-8-10","src":"p2","num":"8.10","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":57,"stem":"Which of the following defines a COMPLEX febrile seizure?","options":["Generalised, lasting 5 minutes, single episode","Focal, lasting 15 minutes or more, recurring within 24 hours, or followed by a focal deficit","Occurring at a temperature above 40 °C","Occurring in a child under 12 months","Any seizure with a fever"],"answer":1,"keyLetter":"B","explanation":"Later epilepsy risk: 1–2% after a simple febrile seizure — the same as any child — versus 4–12% after complex ones. Febrile seizures occur in 3% of children aged 6 months to 6 years and do not cause brain damage."},
  {"id":"pedsa2-8-11","src":"p2","num":"8.11","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":57,"stem":"Which statement about the management of febrile seizures is correct?","options":["Regular antiepileptic prophylaxis should be started after the second seizure","Antipyretics have not been shown to prevent febrile seizures","An EEG predicts recurrence","Lumbar puncture is never indicated","Recurrence occurs in fewer than 5%"],"answer":1,"keyLetter":"B","explanation":"30–40% have another febrile seizure. Under 18 months the signs of meningitis may be absent, so an infection screen including lumbar puncture may be needed. Rescue buccal midazolam is provided if seizures last more than 5 minutes."},
  {"id":"pedsa2-8-12","src":"p2","num":"8.12","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":58,"stem":"A toddler bumps his head, goes very PALE, collapses and has a brief convulsion, then sleeps. What is the diagnosis?","options":["Breath-holding spell","Reflex asystolic syncope (reflex anoxic seizure)","Epilepsy","Long QT syndrome","Febrile seizure"],"answer":1,"keyLetter":"B","explanation":"Triggered by sudden pain, cold food, fright or fever; caused by cardiac asystole from excessive vagal inhibition. Contrast breath-holding spells: an angry toddler who cries first and turns BLUE."},
  {"id":"pedsa2-8-13","src":"p2","num":"8.13","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":58,"stem":"Which set of signs indicates a CEREBELLAR rather than pyramidal disorder?","options":["Brisk reflexes and extensor plantars","Past-pointing, dysdiadochokinesis, wide-based gait, nystagmus and scanning dysarthria","Chorea and athetosis","Fasciculation and absent reflexes","Waddling gait with Gowers' sign"],"answer":1,"keyLetter":"B","explanation":"Causes in childhood include acute intoxication, post-infectious cerebellitis, medulloblastoma, Friedreich ataxia and ataxia telangiectasia. Chorea and athetosis point to the basal ganglia (post-streptococcal chorea, Wilson disease)."},
  {"id":"pedsa2-8-14","src":"p2","num":"8.14","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":59,"stem":"What exactly is Gowers' sign, and when is it abnormal?","options":["Climbing up the legs with the hands; abnormal at any age","The need to turn PRONE in order to rise from supine; normal until 3 years of age","Waddling gait; abnormal after 18 months","Toe walking; abnormal after 5 years","Inability to stand on one leg; abnormal after 4 years"],"answer":1,"keyLetter":"B","explanation":"Turning prone is the early feature; climbing up the legs is the late one. Any child still doing this after 3 years needs investigation — starting with a creatine kinase, which is markedly raised in Duchenne and Becker muscular dystrophy."},
  {"id":"pedsa2-8-15","src":"p2","num":"8.15","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":59,"stem":"A 4-month-old is floppy with absent antigravity movements, absent tendon reflexes, tongue fasciculation and a frog-like posture, but is alert and socially responsive. Where is the lesion?","options":["Cerebral cortex","Anterior horn cell","Basal ganglia","Cerebellum","Peripheral sensory nerves"],"answer":1,"keyLetter":"B","explanation":"Floppy AND weak with absent reflexes = peripheral; fasciculation and an alert infant point to spinal muscular atrophy type 1 (Werdnig–Hoffmann). Floppy but STRONG with brisk reflexes = central — hypoxic–ischaemic injury, trisomy 21, Prader–Willi, hypothyroidism."},
  {"id":"pedsa2-8-16","src":"p2","num":"8.16","kind":"sba","block":"Block 8 · Neurological Disorders 16 QUESTIONS","page":60,"stem":"Which is the commonest cause of OBSTRUCTIVE (non-communicating) hydrocephalus in a preterm infant?","options":["Intraventricular haemorrhage","Subarachnoid haemorrhage","Pneumococcal meningitis","Choroid plexus papilloma","Chiari malformation"],"answer":0,"keyLetter":"A","explanation":"Obstructive causes: aqueduct stenosis, Chiari malformation, posterior fossa tumour, intraventricular haemorrhage. Communicating causes (failure of reabsorption): subarachnoid haemorrhage and meningitis. Watch the head circumference crossing centiles; sun-setting eyes is advanced. Treatment is a ventriculoperitoneal shunt."},
  {"id":"pedsa2-9-1","src":"p2","num":"9.1","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":61,"stem":"How much does an average baby cry at 6 weeks of age?","options":["About 15 minutes a day","About 2 hours a day, falling to about 1 hour a day by 10 weeks","About 6 hours a day","Only when hungry","Crying at this age is always abnormal"],"answer":1,"keyLetter":"B","explanation":"Crying peaks at around 6 weeks and reduces significantly by 3–4 months. Knowing the normal range is what makes reassurance credible."},
  {"id":"pedsa2-9-2","src":"p2","num":"9.2","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":61,"stem":"Which medical cause of excessive crying must never be missed?","options":["Teething","Unrecognised trauma such as an occult fracture","Wind","Growth spurt","Overstimulation"],"answer":1,"keyLetter":"B","explanation":"Medical causes are a minority but include urinary or ear infection, meningitis, obstructed bowel, strangulated hernia, testicular torsion, reflux, cow's milk protein allergy and unrecognised trauma. A full examination and a documented weight are mandatory."},
  {"id":"pedsa2-9-3","src":"p2","num":"9.3","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":62,"stem":"A mother says her 7-week-old \"cries all the time\". He is thriving, examination is normal, and she is tearful and exhausted. What is the most important element of management?","options":["Change the formula","Acknowledge the distress, reassure with objective evidence, and assess maternal mood and support","Prescribe a sedative","Advise leaving the baby to cry","Arrange an abdominal X-ray"],"answer":1,"keyLetter":"B","explanation":"Persistent crying is a recognised warning of parental stress and potential child maltreatment. Reassure with 6 or more wet nappies a day and normal weight gain; changing formula usually does not help; there is some evidence for the probiotic Limosilactobacillus reuteri in breastfed infants."},
  {"id":"pedsa2-9-4","src":"p2","num":"9.4","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":62,"stem":"A mother is worried that her thriving 3-year-old \"eats nothing\" at mealtimes. What is the single most useful question?","options":["Which brand of food do you buy?","How much does he eat BETWEEN meals?","Does he take vitamins?","How tall is his father?","Does he eat at nursery?"],"answer":1,"keyLetter":"B","explanation":"A well-nourished child is getting food from somewhere — and not all parents count sweets and crisps as food. Advice: avoid confrontation, keep mealtimes relaxed, use favourite foods and privileges as rewards, and reduce snacking if needed. A food diary settles the argument."},
  {"id":"pedsa2-9-5","src":"p2","num":"9.5","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":63,"stem":"Which best distinguishes a night terror from a nightmare?","options":["Night terrors occur in the early hours of the morning","In a night terror the child has eyes open, appears awake but is unresponsive, and has NO recollection in the morning","Nightmares cannot be recalled","Night terrors respond to sedatives","Nightmares only occur after trauma"],"answer":1,"keyLetter":"B","explanation":"Night terrors occur about 1.5 hours after settling and are a parasomnia — a disorder of arousal. Sleepwalking shares the same origin, and the priority there is making the environment safe. A regular sleep routine reduces both."},
  {"id":"pedsa2-9-6","src":"p2","num":"9.6","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":63,"stem":"A 6-year-old soils his pants with loose stool several times a day and has a palpable abdominal faecal mass. What is the management?","options":["Antidiarrhoeal medication","Disimpaction with an escalating laxative regimen, then maintenance laxatives with toilet retraining","Psychological therapy alone","Reassurance — this is normal at 6 years","Immediate spinal MRI"],"answer":1,"keyLetter":"B","explanation":"Overflow soiling: liquid stool passes around a faecal mass and the child is unaware of the need to empty. Soiling after 4 years is always abnormal. Retraining takes weeks, with a regular laxative throughout, while the distended rectum returns to normal size."},
  {"id":"pedsa2-9-7","src":"p2","num":"9.7","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":64,"stem":"Which additional feature in a soiling child would point to an occult spinal abnormality?","options":["Urinary incontinence","A history of an anal fissure","Refusing to use the school toilet","A family history of constipation","Recent house move"],"answer":0,"keyLetter":"A","explanation":"Neuropathic bowel from an occult spinal lesion is usually accompanied by urinary incontinence. Examine the back, perineal sensation, anal tone, leg reflexes and gait, and look for S2–S4 sensory loss."},
  {"id":"pedsa2-9-8","src":"p2","num":"9.8","kind":"sba","block":"Block 9 · Child and Adolescent Mental Health 8 QUESTIONS","page":64,"stem":"Which is required for a diagnosis of Gilles de la Tourette syndrome?","options":["Coprolalia","Multiple motor tics AND vocal tics present for over one year","Onset before 4 years of age","An abnormal MRI","Complete inability to suppress the tics"],"answer":1,"keyLetter":"B","explanation":"Coprolalia occurs in only about 10%. Tics affect 1 in 10 children, more boys, onset around 8 years, peaking at 11 years; they are worse when inactive, better when concentrating, and partially suppressible. First-line treatment is cognitive behavioural therapy with habit reversal, with clonidine or risperidone reserved for severe cases."},
  {"id":"pedsa2-10-1","src":"p2","num":"10.1","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":65,"stem":"What proportion of children with diabetes have type 1?","options":["About 50%","About 75%","About 95%","About 30%","Fewer than 10%"],"answer":2,"keyLetter":"C","explanation":"Type 1 is autoimmune β-cell destruction, with antibodies to GAD, ZnT8 and IA-2. Twin risk is about 70% within 3 years versus 15% in other siblings."},
  {"id":"pedsa2-10-2","src":"p2","num":"10.2","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":65,"stem":"Which combination is diagnostic of diabetes in a symptomatic child?","options":["Random glucose above 11.1 mmol/L with glycosuria","Fasting glucose of 6 mmol/L","HbA1c of 40 mmol/mol","Glycosuria alone","A positive glucose tolerance test is always required"],"answer":0,"keyLetter":"A","explanation":"If there is doubt, use a fasting glucose above 7 mmol/L or a raised HbA1c. A glucose tolerance test is rarely needed for type 1 but may be required for type 2."},
  {"id":"pedsa2-10-3","src":"p2","num":"10.3","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":66,"stem":"Which finding suggests type 2 rather than type 1 diabetes in a 13-year-old?","options":["Weight loss and ketosis","Obesity with acanthosis nigricans, skin tags and a strong family history","Presentation in spring","Positive GAD antibodies","Rapid onset over 2 weeks"],"answer":1,"keyLetter":"B","explanation":"Type 2 reflects insulin resistance then β-cell failure and is commoner in some ethnic groups. Look also for a polycystic ovary phenotype in adolescent girls."},
  {"id":"pedsa2-10-4","src":"p2","num":"10.4","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":66,"stem":"Which two misdiagnoses classically delay recognition of diabetic ketoacidosis?","options":["Pneumonia (from the rapid breathing) and appendicitis or constipation (from the abdominal pain)","Asthma and croup","Meningitis and otitis media","Urinary infection and reflux","Migraine and epilepsy"],"answer":0,"keyLetter":"A","explanation":"Which is why a bedside glucose belongs in the assessment of every child with unexplained tachypnoea, vomiting or abdominal pain."},
  {"id":"pedsa2-10-5","src":"p2","num":"10.5","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":66,"stem":"What is the pre-meal blood glucose target for a child with type 1 diabetes?","options":["2–4 mmol/L","4–7 mmol/L","7–11 mmol/L","10–15 mmol/L","Below 2.6 mmol/L"],"answer":1,"keyLetter":"B","explanation":"Insulin requirements are 0.5–1 unit/kg/day, rising to 2 units/kg/day in puberty, after an initial honeymoon period when requirements may be minimal."},
  {"id":"pedsa2-10-6","src":"p2","num":"10.6","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":67,"stem":"Which statement about HbA1c is correct?","options":["It reflects control over the previous week","It reflects control over 6–12 weeks and is unreliable in sickle cell trait and thalassaemia","It should be measured once a year","The target is below 70 mmol/mol","It is unaffected by red cell lifespan"],"answer":1,"keyLetter":"B","explanation":"Check it at least four times a year; the target is below 48 mmol/mol (6.5%). Time in range above 70% correlates with an HbA1c in target."},
  {"id":"pedsa2-10-7","src":"p2","num":"10.7","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":67,"stem":"A child with type 1 diabetes is unconscious in the emergency department with a glucose of 1.9 mmol/L. What is given?","options":["Oral glucose gel","2 mL/kg of intravenous 10% glucose","Subcutaneous insulin","0.9% saline bolus alone","Nothing until a laboratory glucose returns"],"answer":1,"keyLetter":"B","explanation":"Outside hospital or when access is delayed, IM glucagon is used. After recovery, give a complex carbohydrate to stop the glucose falling again. Frequent hypos cause loss of awareness and must be avoided."},
  {"id":"pedsa2-10-8","src":"p2","num":"10.8","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":68,"stem":"Which set of results confirms diabetic ketoacidosis?","options":["Glucose above 11 mmol/L, blood ketones above 3.0 mmol/L, pH below 7.3 or bicarbonate below 15 mmol/L","Glucose above 7 mmol/L with glycosuria only","Ketonuria with a normal pH","pH below 7.3 with a normal glucose","Raised HbA1c alone"],"answer":0,"keyLetter":"A","explanation":"Severity: mild pH <7.2 or bicarbonate 10–15; moderate pH 7.1–7.2 or bicarbonate 5–10; severe pH <7.1 or bicarbonate <5."},
  {"id":"pedsa2-10-9","src":"p2","num":"10.9","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":68,"stem":"Which statement about DKA management is correct?","options":["Insulin should be started immediately with the first fluid bolus","Insulin is started after one hour of fluids at 0.05 units/kg/hour, and the deficit is replaced over 48 hours","Bicarbonate should be given if the pH is below 7.0","The IV insulin is stopped at the same moment as the first subcutaneous dose","Potassium should be withheld throughout"],"answer":1,"keyLetter":"B","explanation":"No bicarbonate. The IV insulin continues for an hour AFTER the first subcutaneous dose because subcutaneous insulin takes time to absorb. Watch the ECG for hypokalaemia — total body potassium is depleted even when the plasma level looks normal."},
  {"id":"pedsa2-10-10","src":"p2","num":"10.10","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":69,"stem":"From what age are annual blood pressure, microalbuminuria and retinal screening recommended in childhood diabetes?","options":["At diagnosis","From 12 years of age","From 16 years of age","Only in type 2 diabetes","Only if the HbA1c is above target"],"answer":1,"keyLetter":"B","explanation":"Coeliac and thyroid screening are done at diagnosis, with thyroid repeated annually. Growth, weight and BMI are plotted at every visit, and injection sites are checked for lipohypertrophy."},
  {"id":"pedsa2-10-11","src":"p2","num":"10.11","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":69,"stem":"What defines hypoglycaemia in a child WITHOUT diabetes?","options":["Below 4 mmol/L","Below 2.6 mmol/L","Below 5 mmol/L","Below 1.0 mmol/L","Any symptomatic reading"],"answer":1,"keyLetter":"B","explanation":"Infants are at particular risk because of high energy requirements, poor gluconeogenic and glycogen reserves and rapid brain growth — which is why starvation beyond 4 hours (e.g. preoperatively) requires an IV glucose-containing infusion."},
  {"id":"pedsa2-10-12","src":"p2","num":"10.12","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":70,"stem":"A 2-year-old presents with an unexplained hypoglycaemic seizure. What must be done at the time of the hypoglycaemia?","options":["Collect diagnostic blood (insulin, C-peptide, cortisol, growth hormone, ketones, lactate, ammonia, acylcarnitines) and save the first urine for organic acids","Give hydrocortisone before any samples","Book a fasting study for the following week","Only repeat the bedside glucose","Arrange an MRI first"],"answer":0,"keyLetter":"A","explanation":"The results may only be abnormal during the episode — the diagnostic opportunity is otherwise lost. A low bedside reading must also be confirmed in the laboratory."},
  {"id":"pedsa2-10-13","src":"p2","num":"10.13","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":70,"stem":"A slim 3-year-old becomes hypoglycaemic after a short fast during a viral illness, with high ketones and low insulin. What is the diagnosis?","options":["Hyperinsulinism","Ketotic hypoglycaemia","Glycogen storage disease","Congenital adrenal hyperplasia","Insulinoma"],"answer":1,"keyLetter":"B","explanation":"Ketotic hypoglycaemia — limited gluconeogenic reserve in a slim young child; prevented by regular carbohydrate and extra glucose drinks when ill, and it resolves spontaneously in later life. Non-ketotic hypoglycaemia with high glucose requirements suggests hyperinsulinism, treated with diazoxide. Hepatomegaly suggests a glycogen storage disorder."},
  {"id":"pedsa2-10-14","src":"p2","num":"10.14","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":71,"stem":"Congenital hypothyroidism is detected on the newborn blood spot by measuring which analyte, and by when must treatment start?","options":["Free T4; by 6 weeks","TSH; before 2 weeks of age","Thyroglobulin; by 3 months","Reverse T3; by 1 week","TSH; by 6 months"],"answer":1,"keyLetter":"B","explanation":"Incidence 1 in 3000; the commonest cause is thyroid agenesis, then maldescent, then dyshormonogenesis (10%). Because screening uses TSH, it misses secondary (pituitary) hypothyroidism. Untreated it is a preventable cause of severe learning difficulty."},
  {"id":"pedsa2-10-15","src":"p2","num":"10.15","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":71,"stem":"A 12-year-old girl has fallen from the 50th to the 9th centile for height while gaining weight, with constipation, dry skin and slow-relaxing reflexes. What is the most likely diagnosis?","options":["Simple obesity","Acquired (autoimmune) hypothyroidism","Cushing syndrome only","Growth hormone excess","Anorexia nervosa"],"answer":1,"keyLetter":"B","explanation":"Short and gaining weight = hypothyroid until proven otherwise; simple obesity makes children TALL. Expect high TSH with low T4 and a delayed bone age; there is an increased risk in Down and Turner syndrome. Also consider slipped upper femoral epiphysis as a complication."},
  {"id":"pedsa2-10-16","src":"p2","num":"10.16","kind":"sba","block":"Block 10 · Diabetes and Endocrinology 16 QUESTIONS","page":72,"stem":"A 2-week-old boy is collapsed with vomiting and weight loss. Sodium 122 mmol/L, potassium 7.1 mmol/L, glucose 1.9 mmol/L, with metabolic acidosis. What is the diagnosis and immediate treatment?","options":["Pyloric stenosis — correct the alkalosis then operate","Salt-losing congenital adrenal hyperplasia — IV saline, glucose and hydrocortisone","Gastroenteritis — oral rehydration","Duct-dependent coarctation — prostaglandin alone","Urinary tract infection — oral antibiotics"],"answer":1,"keyLetter":"B","explanation":"Over 90% of CAH is 21-hydroxylase deficiency (about 1 in 15 000, autosomal recessive), confirmed by a markedly raised 17α-hydroxyprogesterone — but treatment must not wait for the result. Pyloric stenosis gives the opposite picture: hypochloraemic, hypokalaemic ALKALOSIS."},
  {"id":"pedsa2-11-1","src":"p2","num":"11.1","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":73,"stem":"By what age should neonatal jaundice have resolved, beyond which investigation is mandatory?","options":["7 days at term","14 days at term, or 3 weeks if preterm","6 weeks in all babies","3 months","Only if the baby is unwell"],"answer":1,"keyLetter":"B","explanation":"90% of physiological jaundice has resolved by 2 weeks. The first step is to split the bilirubin and ask about stool colour."},
  {"id":"pedsa2-11-2","src":"p2","num":"11.2","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":73,"stem":"Which cause of prolonged neonatal jaundice produces CONJUGATED hyperbilirubinaemia?","options":["Breast-milk jaundice","Biliary atresia","G6PD deficiency","Hypothyroidism","Crigler–Najjar syndrome"],"answer":1,"keyLetter":"B","explanation":"Conjugated causes: biliary atresia, choledochal cyst, neonatal hepatitis syndrome, α1-antitrypsin deficiency, galactosaemia, tyrosinaemia, cystic fibrosis, Alagille, PFIC and TPN-associated disease. The rest listed are unconjugated."},
  {"id":"pedsa2-11-3","src":"p2","num":"11.3","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":74,"stem":"A 6-week-old has persistent jaundice, chalky white stools and dark urine, with hepatomegaly and faltering growth. What is the diagnosis and why does timing matter?","options":["Breast-milk jaundice — no action needed","Biliary atresia — a Kasai portoenterostomy before 60 days clears the jaundice in about 60%","Neonatal hepatitis — steroids","Haemolysis — transfusion","Hypothyroidism — thyroxine"],"answer":1,"keyLetter":"B","explanation":"Biliary atresia occurs in 1 in 15 000; investigations show raised conjugated bilirubin and GGT with a contracted or absent gallbladder. Without intervention, chronic liver failure and death follow within 2 years, and it is the commonest indication for paediatric liver transplantation."},
  {"id":"pedsa2-11-4","src":"p2","num":"11.4","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":74,"stem":"Which triad of symptoms defines cholestasis?","options":["Dark urine, pale stools and pruritus","Pale urine, dark stools and pruritus","Vomiting, diarrhoea and fever","Splenomegaly, anaemia and jaundice","Ascites, oedema and encephalopathy"],"answer":0,"keyLetter":"A","explanation":"Conjugated bilirubin refluxes into blood and is excreted renally (dark urine); no stercobilinogen reaches the gut (pale stool); bile acids deposit in skin (pruritus)."},
  {"id":"pedsa2-11-5","src":"p2","num":"11.5","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":75,"stem":"Which features characterise Alagille syndrome?","options":["Autosomal recessive with bile salt transport defects","Autosomal dominant with triangular facies, butterfly vertebrae and peripheral pulmonary stenosis","X-linked with deafness","Trisomy with duodenal atresia","Acquired after parenteral nutrition"],"answer":1,"keyLetter":"B","explanation":"Most survive into adult life, and mortality is most often secondary to the cardiac disease. Option A describes progressive familial intrahepatic cholestasis, treated with nutrition, fat-soluble vitamins and ileal bile acid transporter inhibitors for pruritus."},
  {"id":"pedsa2-11-6","src":"p2","num":"11.6","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":75,"stem":"Which protein phenotype of α1-antitrypsin deficiency is associated with liver disease?","options":["PiMM","PiZZ","PiMS","PiSS only","No phenotype predicts liver disease"],"answer":1,"keyLetter":"B","explanation":"Autosomal recessive, 1 in 2000–4000 in the UK, gene on chromosome 14. Abnormal folding causes accumulation WITHIN hepatocytes (liver disease), while lack of circulating enzyme causes emphysema in adults — so smoking, active and passive, must be avoided. About 50% of children do well."},
  {"id":"pedsa2-11-7","src":"p2","num":"11.7","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":76,"stem":"A jaundiced newborn with poor feeding develops E. coli sepsis, and reducing substances are found in the urine. What is the likely diagnosis, and what could mask it?","options":["Galactosaemia; a recent blood transfusion masks the red cell enzyme assay","Biliary atresia; antibiotics mask the diagnosis","Hypothyroidism; phototherapy masks it","Hepatitis B; maternal antibody masks it","G6PD deficiency; a high reticulocyte count masks it"],"answer":0,"keyLetter":"A","explanation":"Galactosaemia is confirmed by measuring galactose-1-phosphate-uridyl transferase in red cells. Untreated it causes liver failure, cataracts and developmental delay; a galactose-free diet prevents liver disease, but ovarian failure and learning difficulties may still occur."},
  {"id":"pedsa2-11-8","src":"p2","num":"11.8","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":76,"stem":"Which hepatitis virus never causes chronic liver disease?","options":["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis D","Hepatitis E in the immunosuppressed"],"answer":0,"keyLetter":"A","explanation":"Hepatitis A is an RNA virus spread faecal–orally; most children recover within 2–4 weeks. Close contacts should be vaccinated within 2 weeks of onset. Note that 30–50% of children with acute viral hepatitis do not become jaundiced."},
  {"id":"pedsa2-11-9","src":"p2","num":"11.9","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":77,"stem":"What proportion of infants who acquire hepatitis B perinatally become chronic carriers?","options":["Fewer than 10%","About 50%","At least 90%","None — perinatal infection always clears","About 25%"],"answer":2,"keyLetter":"C","explanation":"They are asymptomatic but become carriers, which is why vaccination (with immunoglobulin where advised) at birth matters so much. 30–50% of carrier children develop chronic liver disease, about 10% progressing to cirrhosis, with a long-term risk of hepatocellular carcinoma."},
  {"id":"pedsa2-11-10","src":"p2","num":"11.10","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":77,"stem":"A child's serology shows HBsAg negative, anti-HBs positive, anti-HBc positive. What does this mean?","options":["Successful vaccination only","Past natural infection with recovery","Acute infection","Chronic carrier with high infectivity","No exposure to hepatitis B"],"answer":1,"keyLetter":"B","explanation":"Anti-HBc is produced only by real infection, never by vaccination. Vaccination gives anti-HBs alone. HBsAg = infectious now; HBeAg = highly transmissible; anti-HBc IgM = acute."},
  {"id":"pedsa2-11-11","src":"p2","num":"11.11","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":78,"stem":"Which fat-soluble vitamin deficiency in chronic cholestasis causes bleeding, including intracranial haemorrhage?","options":["Vitamin A","Vitamin D","Vitamin E","Vitamin K","Vitamin C"],"answer":3,"keyLetter":"D","explanation":"The others: A — night blindness; D — rickets and fractures; E — peripheral neuropathy, haemolysis and ataxia. Cholestatic infants need a medium-chain triglyceride formula, keeping about 40% of fat as long-chain to prevent essential fatty acid deficiency."},
  {"id":"pedsa2-11-12","src":"p2","num":"11.12","kind":"sba","block":"Block 11 · Liver Disorders 12 QUESTIONS","page":78,"stem":"A 14-year-old with abnormal liver function has deteriorating school performance, mood change, a tremor and dysarthria. Which diagnosis must be excluded?","options":["Wilson disease","Hepatitis A","Gilbert syndrome","Biliary atresia","Alagille syndrome"],"answer":0,"keyLetter":"A","explanation":"A rare but TREATABLE cause of liver failure. Neuropsychiatric features appear from the second decade, with extrapyramidal signs and Kayser–Fleischer rings from corneal copper. Remember too that in cirrhosis the markers of function are the albumin and prothrombin time, not the transaminases."},
  {"id":"pedsa2-12-1","src":"p2","num":"12.1","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":79,"stem":"What is the approximate risk that a child develops cancer before the age of 15 years?","options":["1 in 50","1 in 500","1 in 5000","1 in 50 000","1 in 5"],"answer":1,"keyLetter":"B","explanation":"About 120–140 new cases per million children under 15 each year. Overall 5-year survival is about 75%, but over 60% of survivors live with at least one chronic condition related to the disease or its treatment."},
  {"id":"pedsa2-12-2","src":"p2","num":"12.2","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":79,"stem":"Which tumours are \"embryonal\" and almost always present in the first 6 years of life?","options":["Neuroblastoma and Wilms tumour","Osteosarcoma and Ewing sarcoma","Hodgkin lymphoma and thyroid carcinoma","Astrocytoma and ependymoma","Testicular germ cell tumours"],"answer":0,"keyLetter":"A","explanation":"Childhood cancer types differ completely from adults, where lung, breast, bowel and prostate carcinomas predominate."},
  {"id":"pedsa2-12-3","src":"p2","num":"12.3","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":80,"stem":"A child on chemotherapy has a temperature of 38.5 °C and a neutrophil count of 0.3 × 10⁹/L. What is the correct action?","options":["Oral antibiotics and review in 24 hours","Blood cultures and immediate broad-spectrum IV antibiotics","Antipyretics alone","Wait for the culture result before treating","Granulocyte transfusion first"],"answer":1,"keyLetter":"B","explanation":"Febrile neutropenia is a medical emergency. Remember also that measles and varicella zoster are potentially life-threatening in these children, so exposure must be reported immediately."},
  {"id":"pedsa2-12-4","src":"p2","num":"12.4","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":80,"stem":"Which complication is precipitated by STARTING chemotherapy and risks acute renal failure?","options":["Tumour lysis syndrome","SIADH","Superior vena cava obstruction","Hypercalcaemia","Cardiac tamponade"],"answer":0,"keyLetter":"A","explanation":"Prevented by additional hydration and allopurinol — or urate oxidase when the white cell count is high — given BEFORE chemotherapy starts."},
  {"id":"pedsa2-12-5","src":"p2","num":"12.5","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":80,"stem":"Acute lymphoblastic leukaemia accounts for what proportion of childhood leukaemia, and at what age does it peak?","options":["50%, peaking at 10–14 years","80%, peaking at 2–5 years","30%, peaking in infancy","95%, peaking at 8–12 years","20%, peaking at 6 months"],"answer":1,"keyLetter":"B","explanation":"Presentation is usually insidious over several weeks: pallor and lethargy, infection, bruising and petechiae, bone pain, hepatosplenomegaly and lymphadenopathy."},
  {"id":"pedsa2-12-6","src":"p2","num":"12.6","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":81,"stem":"Which is a HIGH-RISK prognostic feature in acute lymphoblastic leukaemia?","options":["Age 3 years","White cell count above 50 × 10⁹/L at presentation","Common B-precursor immunophenotype","Undetectable minimal residual disease after induction","Hyperdiploidy"],"answer":1,"keyLetter":"B","explanation":"Other high-risk features: age under 1 or over 10 years, MLL rearrangement or t(4;11), hypodiploidy (<44 chromosomes), and detectable minimal residual disease after induction."},
  {"id":"pedsa2-12-7","src":"p2","num":"12.7","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":81,"stem":"Why is intrathecal chemotherapy given in acute lymphoblastic leukaemia?","options":["To reduce nausea","Because leukaemic cells in the CNS may survive effective systemic treatment","To treat bone pain","To prevent tumour lysis","To shorten maintenance therapy"],"answer":1,"keyLetter":"B","explanation":"The CNS is a sanctuary site. Maintenance chemotherapy continues for up to 3 years from diagnosis, with co-trimoxazole prophylaxis against Pneumocystis; induction achieves remission in about 95%."},
  {"id":"pedsa2-12-8","src":"p2","num":"12.8","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":81,"stem":"What proportion of childhood brain tumours are infratentorial?","options":["10%","30%","60%","90%","Fewer than 5%"],"answer":2,"keyLetter":"C","explanation":"Almost all are primary rather than metastatic. They are the commonest solid tumour of childhood and the leading cause of childhood cancer death. Astrocytoma ~40%, medulloblastoma ~20%, ependymoma ~8%, brainstem glioma ~6%, craniopharyngioma ~4%."},
  {"id":"pedsa2-12-9","src":"p2","num":"12.9","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":82,"stem":"A 10-year-old has headaches, vomiting, poor growth and cannot see the board at school. Examination shows a bitemporal field defect. What is the most likely tumour?","options":["Medulloblastoma","Craniopharyngioma","Brainstem glioma","Ependymoma","Glioblastoma multiforme"],"answer":1,"keyLetter":"B","explanation":"A suprasellar tumour compressing the optic chiasm and pituitary: bitemporal hemianopia, growth failure, diabetes insipidus, weight gain. It is not truly malignant but locally invasive — survival is good, but at the cost of visual impairment and lifelong pituitary insufficiency."},
  {"id":"pedsa2-12-10","src":"p2","num":"12.10","kind":"sba","block":"Block 12 · Malignant Disease 10 QUESTIONS","page":82,"stem":"A 3-year-old has morning vomiting, truncal ataxia and a convergent squint. Which statement is correct?","options":["A lumbar puncture should be performed immediately","MRI is the investigation of choice; lumbar puncture is done later, for CSF staging, and never before imaging","Papilloedema must be present to justify imaging","Seizures are the usual presenting feature of posterior fossa tumours","Medulloblastoma never metastasises"],"answer":1,"keyLetter":"B","explanation":"A posterior fossa tumour, most likely medulloblastoma — which seeds through the CSF, with up to 20% having spinal metastases at diagnosis and a 5-year survival of about 50%. Papilloedema is a late sign and its absence never excludes raised pressure."},
  {"id":"pedsa2-m-21","src":"p2","num":"13.21","kind":"mock","block":"Mixed mock — four final questions","page":88,"stem":"Which single examination finding, if absent, most reliably makes duct-dependent coarctation unlikely in a collapsed neonate?","options":["A parasternal thrill","Palpable femoral pulses","Hepatomegaly","A loud second heart sound","Central cyanosis"],"answer":1,"keyLetter":"B","explanation":"Absent femoral pulses are the cardinal sign — which is why palpating them is mandatory in every neonatal and murmur examination."},
  {"id":"pedsa2-m-22","src":"p2","num":"13.22","kind":"mock","block":"Mixed mock — four final questions","page":88,"stem":"A 6-year-old in DKA has had one hour of fluid resuscitation. Which is correct?","options":["Give sodium bicarbonate if the pH is below 7.0","Start an insulin infusion at 0.05 units/kg/hour and replace the deficit over 48 hours","Give the entire deficit over 12 hours","Stop the insulin infusion as soon as the first subcutaneous dose is given","Withhold potassium because the plasma level is normal"],"answer":1,"keyLetter":"B","explanation":"No bicarbonate; the IV insulin continues for one hour after the first subcutaneous dose; and total body potassium is depleted even when the plasma level looks normal."},
  {"id":"pedsa2-m-23","src":"p2","num":"13.23","kind":"mock","block":"Mixed mock — four final questions","page":89,"stem":"Which statement about hepatitis B serology is correct?","options":["Anti-HBs alone indicates natural infection","Anti-HBc indicates true infection and is never produced by vaccination","HBeAg indicates low infectivity","HBsAg indicates immunity","IgG anti-HBc indicates acute infection"],"answer":1,"keyLetter":"B","explanation":"s = sick (HBsAg = infected now; anti-HBs = immune). e = easily spread. c = core, meaning real infection — IgM acute, IgG past or chronic."},
  {"id":"pedsa2-m-24","src":"p2","num":"13.24","kind":"mock","block":"Mixed mock — four final questions","page":89,"stem":"A 9-year-old has had headaches for 8 weeks that are worse on lying down and on coughing, with vomiting on waking, a new convergent squint and an unsteady gait. Fundoscopy is normal. What is the correct next step?","options":["Reassure — normal fundi exclude raised intracranial pressure","Urgent neuroimaging","Lumbar puncture","Start migraine prophylaxis","Refer for refraction"],"answer":1,"keyLetter":"B","explanation":"Every red flag is present, and papilloedema is a LATE sign whose absence excludes nothing. A lumbar puncture before imaging is dangerous when pressure may be raised."},
  {"id":"pedsa2-13-1","src":"p2","num":"13.1","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The murmur","page":83,"stem":"A 4-year-old has an ejection systolic murmur at the upper left sternal edge with a widely split second heart sound that does not vary with respiration. The ECG shows partial right bundle branch block and right axis deviation.","options":["Secundum atrial septal defect","Partial atrioventricular septal defect","Small ventricular septal defect","Large ventricular septal defect","Persistent ductus arteriosus","Tetralogy of Fallot","Transposition of the great arteries","Aortic stenosis","Pulmonary stenosis","Innocent murmur"],"answer":0,"keyLetter":"A","explanation":"A — Secundum ASD. Fixed splitting plus right axis deviation. Device closure at 3–5 years. A superior axis with an apical pansystolic murmur would have made it a partial AVSD."},
  {"id":"pedsa2-13-2","src":"p2","num":"13.2","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The murmur","page":83,"stem":"A 3-month-old is breathless on feeding with faltering growth, an active precordium, a loud second heart sound, an apical mid-diastolic murmur and only a very soft systolic murmur.","options":["Secundum atrial septal defect","Partial atrioventricular septal defect","Small ventricular septal defect","Large ventricular septal defect","Persistent ductus arteriosus","Tetralogy of Fallot","Transposition of the great arteries","Aortic stenosis","Pulmonary stenosis","Innocent murmur"],"answer":3,"keyLetter":"D","explanation":"D — Large VSD. Diuretics, captopril and extra calories, then surgery at 3–6 months to prevent pulmonary vascular disease."},
  {"id":"pedsa2-13-3","src":"p2","num":"13.3","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The murmur","page":83,"stem":"A 2-year-old has a continuous murmur below the left clavicle and bounding pulses, but no symptoms.","options":["Secundum atrial septal defect","Partial atrioventricular septal defect","Small ventricular septal defect","Large ventricular septal defect","Persistent ductus arteriosus","Tetralogy of Fallot","Transposition of the great arteries","Aortic stenosis","Pulmonary stenosis","Innocent murmur"],"answer":4,"keyLetter":"E","explanation":"E — Persistent ductus arteriosus. Continuous because pulmonary pressure is below aortic pressure throughout the cycle. Coil or device closure at about 1 year abolishes the lifelong endocarditis risk."},
  {"id":"pedsa2-13-4","src":"p2","num":"13.4","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The murmur","page":84,"stem":"A 6-year-old has an ejection systolic murmur maximal at the upper RIGHT sternal edge radiating to the neck, a slow-rising pulse and a thrill over the carotids.","options":["Secundum atrial septal defect","Partial atrioventricular septal defect","Small ventricular septal defect","Large ventricular septal defect","Persistent ductus arteriosus","Tetralogy of Fallot","Transposition of the great arteries","Aortic stenosis","Pulmonary stenosis","Innocent murmur"],"answer":7,"keyLetter":"H","explanation":"H — Aortic stenosis. The carotid thrill is what separates it from pulmonary stenosis. Balloon valvotomy if symptomatic on exercise or the resting gradient exceeds 64 mmHg."},
  {"id":"pedsa2-13-5","src":"p2","num":"13.5","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The murmur","page":84,"stem":"A cyanosed neonate on day 2 has no murmur, a loud single second sound and an \"egg on side\" chest X-ray.","options":["Secundum atrial septal defect","Partial atrioventricular septal defect","Small ventricular septal defect","Large ventricular septal defect","Persistent ductus arteriosus","Tetralogy of Fallot","Transposition of the great arteries","Aortic stenosis","Pulmonary stenosis","Innocent murmur"],"answer":6,"keyLetter":"G","explanation":"G — Transposition of the great arteries. Prostaglandin, balloon atrial septostomy in about 20%, then the arterial switch in the neonatal period."},
  {"id":"pedsa2-13-6","src":"p2","num":"13.6","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Blood and protein in the urine","page":84,"stem":"A 7-year-old boy has smoky brown urine, puffy eyes, a blood pressure of 140/95 and reduced urine output. Three weeks earlier he had a sore throat. C3 is low.","options":["Post-streptococcal glomerulonephritis","IgA nephropathy","Henoch–Schönlein purpura","Steroid-sensitive nephrotic syndrome","Haemolytic uraemic syndrome","Urinary tract infection","Orthostatic proteinuria","Alport syndrome","Systemic lupus erythematosus","Hypercalciuria"],"answer":0,"keyLetter":"A","explanation":"A — Post-streptococcal glomerulonephritis. Type III immune-complex disease; the C3 returns to normal in 3–4 weeks and over 95% recover fully."},
  {"id":"pedsa2-13-7","src":"p2","num":"13.7","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Blood and protein in the urine","page":84,"stem":"A 9-year-old has visible haematuria on the second day of a cold, for the third time this year. Complement levels are normal.","options":["Post-streptococcal glomerulonephritis","IgA nephropathy","Henoch–Schönlein purpura","Steroid-sensitive nephrotic syndrome","Haemolytic uraemic syndrome","Urinary tract infection","Orthostatic proteinuria","Alport syndrome","Systemic lupus erythematosus","Hypercalciuria"],"answer":1,"keyLetter":"B","explanation":"B — IgA nephropathy. Haematuria coincides with the infection rather than following it by weeks, and complement is normal."},
  {"id":"pedsa2-13-8","src":"p2","num":"13.8","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Blood and protein in the urine","page":85,"stem":"A 5-year-old has a palpable purpuric rash over the buttocks and extensor surfaces, painful swollen ankles and colicky abdominal pain. Platelets are normal and the urine shows blood and protein.","options":["Post-streptococcal glomerulonephritis","IgA nephropathy","Henoch–Schönlein purpura","Steroid-sensitive nephrotic syndrome","Haemolytic uraemic syndrome","Urinary tract infection","Orthostatic proteinuria","Alport syndrome","Systemic lupus erythematosus","Hypercalciuria"],"answer":2,"keyLetter":"C","explanation":"C — Henoch–Schönlein purpura. The commonest childhood systemic vasculitis. Watch for intussusception, and follow the urine and blood pressure long term."},
  {"id":"pedsa2-13-9","src":"p2","num":"13.9","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Blood and protein in the urine","page":85,"stem":"A 3-year-old is pale and passing very little urine a week after bloody diarrhoea following a farm visit. Platelets 40 × 10⁹/L, fragmented red cells, NORMAL coagulation screen.","options":["Post-streptococcal glomerulonephritis","IgA nephropathy","Henoch–Schönlein purpura","Steroid-sensitive nephrotic syndrome","Haemolytic uraemic syndrome","Urinary tract infection","Orthostatic proteinuria","Alport syndrome","Systemic lupus erythematosus","Hypercalciuria"],"answer":4,"keyLetter":"E","explanation":"E — Haemolytic uraemic syndrome. Verocytotoxin-producing E. coli O157:H7. Normal clotting is what excludes DIC. Supportive care with early dialysis; long-term follow-up for hypertension and CKD."},
  {"id":"pedsa2-13-10","src":"p2","num":"13.10","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Blood and protein in the urine","page":85,"stem":"A well 12-year-old has 2+ protein on a school dipstick. Three early-morning samples show a normal protein:creatinine ratio.","options":["Post-streptococcal glomerulonephritis","IgA nephropathy","Henoch–Schönlein purpura","Steroid-sensitive nephrotic syndrome","Haemolytic uraemic syndrome","Urinary tract infection","Orthostatic proteinuria","Alport syndrome","Systemic lupus erythematosus","Hypercalciuria"],"answer":6,"keyLetter":"G","explanation":"G — Orthostatic proteinuria. Protein appears only when upright. The prognosis is excellent and no further investigation is required."},
  {"id":"pedsa2-13-11","src":"p2","num":"13.11","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The child with an episode of altered consciousness","page":85,"stem":"An 18-month-old has a 20-minute right-sided convulsion during a febrile illness, followed by 2 hours of right arm weakness.","options":["Breath-holding spell","Reflex asystolic syncope","Vasovagal syncope","Long QT syndrome","Simple febrile seizure","Complex febrile seizure","Childhood absence epilepsy","Infantile spasms","Juvenile myoclonic epilepsy","Hypoglycaemia"],"answer":5,"keyLetter":"F","explanation":"F — Complex febrile seizure. Focal, prolonged and followed by a Todd paresis; the later epilepsy risk is 4–12% rather than 1–2%."},
  {"id":"pedsa2-13-12","src":"p2","num":"13.12","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The child with an episode of altered consciousness","page":86,"stem":"A 2-year-old is refused a biscuit, screams, holds his breath in expiration, turns blue and goes limp, then recovers within a minute.","options":["Breath-holding spell","Reflex asystolic syncope","Vasovagal syncope","Long QT syndrome","Simple febrile seizure","Complex febrile seizure","Childhood absence epilepsy","Infantile spasms","Juvenile myoclonic epilepsy","Hypoglycaemia"],"answer":0,"keyLetter":"A","explanation":"A — Breath-holding spell. Angry trigger, cries first, goes BLUE. Drug therapy is unhelpful; treating iron deficiency may reduce attacks."},
  {"id":"pedsa2-13-13","src":"p2","num":"13.13","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The child with an episode of altered consciousness","page":86,"stem":"A 14-year-old collapses while sprinting at school and has a brief convulsion, then recovers fully.","options":["Breath-holding spell","Reflex asystolic syncope","Vasovagal syncope","Long QT syndrome","Simple febrile seizure","Complex febrile seizure","Childhood absence epilepsy","Infantile spasms","Juvenile myoclonic epilepsy","Hypoglycaemia"],"answer":3,"keyLetter":"D","explanation":"D — Long QT syndrome. Exercise-related collapse demands a 12-lead ECG — the reason an ECG is recommended in every child with seizures."},
  {"id":"pedsa2-13-14","src":"p2","num":"13.14","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The child with an episode of altered consciousness","page":86,"stem":"A 7-year-old is described by her teacher as \"switching off\" many times a day for a few seconds with eyelid flickering, then carrying on as if nothing happened.","options":["Breath-holding spell","Reflex asystolic syncope","Vasovagal syncope","Long QT syndrome","Simple febrile seizure","Complex febrile seizure","Childhood absence epilepsy","Infantile spasms","Juvenile myoclonic epilepsy","Hypoglycaemia"],"answer":6,"keyLetter":"G","explanation":"G — Childhood absence epilepsy. Provoked by hyperventilation; EEG shows 3 Hz generalised spike-and-wave; 80% remit in adolescence."},
  {"id":"pedsa2-13-15","src":"p2","num":"13.15","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"The child with an episode of altered consciousness","page":86,"stem":"A 5-month-old has clusters of sudden flexion of the head and trunk with extension of the arms, mostly on waking, and has stopped smiling and reaching.","options":["Breath-holding spell","Reflex asystolic syncope","Vasovagal syncope","Long QT syndrome","Simple febrile seizure","Complex febrile seizure","Childhood absence epilepsy","Infantile spasms","Juvenile myoclonic epilepsy","Hypoglycaemia"],"answer":7,"keyLetter":"H","explanation":"H — Infantile spasms (West syndrome). Loss of skills is the key marker; EEG shows hypsarrhythmia; treat with vigabatrin or corticosteroids."},
  {"id":"pedsa2-13-16","src":"p2","num":"13.16","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Jaundice, pallor and swelling","page":87,"stem":"A 6-week-old has persistent jaundice, chalky pale stools, dark urine, hepatomegaly and faltering growth.","options":["Biliary atresia","Breast-milk jaundice","Congenital hypothyroidism","G6PD deficiency","Galactosaemia","α1-antitrypsin deficiency","Acute lymphoblastic leukaemia","Iron deficiency anaemia","Nephrotic syndrome","Cirrhosis with portal hypertension"],"answer":0,"keyLetter":"A","explanation":"A — Biliary atresia. Conjugated hyperbilirubinaemia with raised GGT. The Kasai must be done before 60 days — 60% then clear their jaundice."},
  {"id":"pedsa2-13-17","src":"p2","num":"13.17","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Jaundice, pallor and swelling","page":87,"stem":"A 3-week-old is jaundiced and constipated with a large tongue, a hoarse cry and an umbilical hernia; the bilirubin is unconjugated.","options":["Biliary atresia","Breast-milk jaundice","Congenital hypothyroidism","G6PD deficiency","Galactosaemia","α1-antitrypsin deficiency","Acute lymphoblastic leukaemia","Iron deficiency anaemia","Nephrotic syndrome","Cirrhosis with portal hypertension"],"answer":2,"keyLetter":"C","explanation":"C — Congenital hypothyroidism. Detected by a raised TSH on the newborn blood spot; thyroxine must start before 2 weeks of age."},
  {"id":"pedsa2-13-18","src":"p2","num":"13.18","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Jaundice, pallor and swelling","page":87,"stem":"A 4-year-old boy becomes acutely pale and jaundiced with dark urine two days after a meal of fava beans.","options":["Biliary atresia","Breast-milk jaundice","Congenital hypothyroidism","G6PD deficiency","Galactosaemia","α1-antitrypsin deficiency","Acute lymphoblastic leukaemia","Iron deficiency anaemia","Nephrotic syndrome","Cirrhosis with portal hypertension"],"answer":3,"keyLetter":"D","explanation":"D — G6PD deficiency. X-linked; triggers include fava beans, infection and oxidant drugs. Check the enzyme level after the acute episode."},
  {"id":"pedsa2-13-19","src":"p2","num":"13.19","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Jaundice, pallor and swelling","page":87,"stem":"A 4-year-old has been pale and lethargic for 6 weeks with intermittent fever, and now has petechiae, lymphadenopathy, mild hepatosplenomegaly and complains of leg pain.","options":["Biliary atresia","Breast-milk jaundice","Congenital hypothyroidism","G6PD deficiency","Galactosaemia","α1-antitrypsin deficiency","Acute lymphoblastic leukaemia","Iron deficiency anaemia","Nephrotic syndrome","Cirrhosis with portal hypertension"],"answer":6,"keyLetter":"G","explanation":"G — Acute lymphoblastic leukaemia. Marrow failure plus organ infiltration; bone marrow examination is definitive. Bone pain in a pale, bruising child is never \"growing pains\"."},
  {"id":"pedsa2-13-20","src":"p2","num":"13.20","kind":"emq","block":"Block 13 · EMQ Sets + Mixed Mock Paper 24 QUESTIONS","setTitle":"Jaundice, pallor and swelling","page":88,"stem":"A 4-year-old has puffy eyes worst on waking, ascites, 4+ proteinuria and an albumin of 14 g/L, with a normal blood pressure and normal complement.","options":["Biliary atresia","Breast-milk jaundice","Congenital hypothyroidism","G6PD deficiency","Galactosaemia","α1-antitrypsin deficiency","Acute lymphoblastic leukaemia","Iron deficiency anaemia","Nephrotic syndrome","Cirrhosis with portal hypertension"],"answer":8,"keyLetter":"I","explanation":"I — Steroid-sensitive nephrotic syndrome. All the typical features: treat with prednisolone 60 mg/m²/day for 4 weeks, then 40 mg/m² on alternate days."}
];
